  state.last_checked_at = nowIso;
  state.stable_for_s = Math.floor(stableForMs / 1000);
  flow.set(KEY, state, "persistent");
  flow.set(HISTORY_KEY, {
    last_outage_at: state.last_outage_at,
    last_recovery_at: state.last_recovery_at,
    last_outage_duration_s: state.last_outage_duration_s,
  }, "persistent");
  const attributes = {
    state: state.phase,
    raw_state: rawState,
    stable_for_s: state.stable_for_s,
    checked_at: nowIso,
    last_outage: state.last_outage_at || "Nenhuma queda confirmada",
    last_recovery: state.last_recovery_at || "Nenhuma recuperação registrada",
    last_outage_duration_s: state.last_outage_duration_s,
    failure_confirmation_s: 30,
    recovery_confirmation_s: 60,
    reminder_interval_h: REMINDER_INTERVAL_MS / (60 * 60 * 1000),
    next_reminder: state.incident_open ? state.next_reminder_at : null,
  };
  const publications = [
    { topic: "nodered/infrastructure/zigbee/connection", payload: state.phase === "online" ? "ON" : "OFF" },
    { topic: "nodered/infrastructure/zigbee/attributes", payload: JSON.stringify(attributes) },
    { topic: "nodered/infrastructure/zigbee/state", payload: state.phase },
  ];
  node.status({
    fill: state.phase === "online" ? "green" : state.phase === "offline" ? "red" : "yellow",
    shape: state.phase === "online" ? "dot" : "ring",
    text: `${state.phase}: ${rawState}`,
  });
  return [downNotification, recoveryNotification, publications];

const device = {
    identifiers: ["node_red_infrastructure_monitoring"],
    name: "Monitoramento de infraestrutura",
    manufacturer: "Node-RED",
    model: "Flows de disponibilidade",
  };
  const availability = {
    availability_topic: "nodered/status",
    payload_available: "online",
    payload_not_available: "offline",
  };
  return [[
    {
      topic: "homeassistant/binary_sensor/zigbee_network/config",
      payload: JSON.stringify({
        name: "Rede Zigbee",
        object_id: "zigbee_network",
        default_entity_id: "binary_sensor.zigbee_network",
        unique_id: "node_red_zigbee_network",
        device_class: "connectivity",
        state_topic: "nodered/infrastructure/zigbee/connection",
        json_attributes_topic: "nodered/infrastructure/zigbee/attributes",
        payload_on: "ON",
        payload_off: "OFF",
        ...availability,
        device,
      }),
    },
    {
      topic: "homeassistant/sensor/zigbee_network_state/config",
      payload: JSON.stringify({
        name: "Estado da rede Zigbee",
        object_id: "zigbee_network_state",
        default_entity_id: "sensor.zigbee_network_state",
        unique_id: "node_red_zigbee_network_state",
        icon: "mdi:zigbee",
        entity_category: "diagnostic",
        state_topic: "nodered/infrastructure/zigbee/state",
        json_attributes_topic: "nodered/infrastructure/zigbee/attributes",
        ...availability,
        device,
      }),
    },
  ]];

const HISTORY_KEY = "zigbee_network_monitor_history_v1";
  let retained = msg.payload;
  if (Buffer.isBuffer(retained)) retained = retained.toString("utf8");
  if (typeof retained === "string") {
    try { retained = JSON.parse(retained); } catch { return null; }
  }
  if (!retained || typeof retained !== "object") return null;
  const current = flow.get(HISTORY_KEY, "persistent") || {};
  const isTimestamp = (value) => typeof value === "string" && Number.isFinite(Date.parse(value));
  if (isTimestamp(retained.last_outage)) current.last_outage_at = retained.last_outage;
  if (isTimestamp(retained.last_recovery)) current.last_recovery_at = retained.last_recovery;
  const durationValue = retained.last_outage_duration_s;
  const duration = Number(durationValue);
  if (durationValue != null && durationValue !== "" && Number.isFinite(duration) && duration >= 0) {
    current.last_outage_duration_s = duration;
  }
  flow.set(HISTORY_KEY, current, "persistent");
  return null;

const KEY = "zigbee_component_incidents_v1";
  const REMINDER_INTERVAL_MS = 24 * 60 * 60 * 1000;
  const incidents = flow.get(KEY, "persistent") || {};
  const now = Number(msg.monitor_now || Date.now());
  const nowIso = new Date(now).toISOString();
  const reminders = [];
  let changed = false;

  for (const [component, incident] of Object.entries(incidents)) {
    if (incident?.offline !== true) continue;
    const lastNotificationMs = Date.parse(incident.last_notification_at || incident.outage_started_at || "");
    let nextReminderMs = Date.parse(incident.next_reminder_at || "");
    if (!Number.isFinite(nextReminderMs)) {
      nextReminderMs = Number.isFinite(lastNotificationMs) ? lastNotificationMs + REMINDER_INTERVAL_MS : now + REMINDER_INTERVAL_MS;
      incident.next_reminder_at = new Date(nextReminderMs).toISOString();
      changed = true;
    }
    if (now < nextReminderMs) continue;

    const slug = component.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");
    let hash = 0x811c9dc5;
    for (const byte of Buffer.from(component, "utf8")) {
      hash ^= byte;
      hash = Math.imul(hash, 0x01000193) >>> 0;
    }
    const notificationKey = `${slug || "component"}_${hash.toString(16).padStart(8, "0")}`;
    incident.last_notification_at = nowIso;
    incident.next_reminder_at = new Date(now + REMINDER_INTERVAL_MS).toISOString();
    changed = true;
    reminders.push({
      notification: {
        id: `zigbee_component_${notificationKey}`,
        title: "Componente Zigbee continua indisponível",
        message: `O componente Zigbee “${component}” continua indisponível há pelo menos 24 horas. Novo lembrete em ${new Date(now).toLocaleString("pt-BR")}. Verifique alimentação, alcance, bateria e a malha Zigbee.`,
      },
    });
  }

  if (changed) flow.set(KEY, incidents, "persistent");
  return reminders.length ? [reminders] : null;

const HOME_LAT = Number(env.get("HOME_LAT"));
const HOME_LON = Number(env.get("HOME_LON"));
const GATE_LAT = Number(env.get("GATE_LAT"));
const GATE_LON = Number(env.get("GATE_LON"));
const HOME_KNOWN = Number.isFinite(HOME_LAT) && Number.isFinite(HOME_LON);
const GATE_KNOWN = Number.isFinite(GATE_LAT) && Number.isFinite(GATE_LON);

const ARM_DISTANCE_M = 100;
const ARRIVAL_DISTANCE_M = 300;
const MAX_GPS_ACCURACY_M = 100;
const APPROACH_ZONE = "chegando";
const PRIMARY_HOME_GRACE_MS = 10 * 60 * 1000;
const LOCATION_FRESH_MS = 15 * 60 * 1000;

const RECOVERY_KEY = "security_people_recovery_v1";
const PERSISTENT = "persistent";
const DEDUPE_TTL_MS = 10 * 60 * 1000;
const FUTURE_TOLERANCE_MS = 60 * 1000;
const ARMED_KEY = "people_arrival_armed";

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const SHARED_TEST_KEY = "security_location_test_state_v1";

function testBaseline(now = Date.now()) {
    return {
        version: 1,
        resident_primary: "home",
        resident_secondary: "home",
        vehicle_primary: "home",
        vehicle_primary_engine: "off",
        vehicle_primary_lock: "locked",
        observed_at: now,
        transitions: {}
    };
}

function clearPeopleTestState() {
    [
        "security_people_recovery_v1__test",
        "people_arrival_armed__test",
        "people_context_v1__test",
        "security_people_ready_logged__test",
        "security_people_test_clock"
    ].forEach((key) => flow.set(key, undefined));
}

/*
 * O snapshot continua vindo do ciclo real do contexto_chegadas.
 * Em TEST_MODE, somente os valores lidos são substituídos pelo
 * estado sintético COMPARTILHADO entre Pessoas e vehicle_primary.
 */
if (
    TEST_MODE &&
    msg.payload?.event === "context_snapshot"
) {
    if (msg._location_test_reset === true) {
        clearPeopleTestState();
    }

    let shared = global.get(SHARED_TEST_KEY);
    if (!shared || shared.version !== 1) {
        shared = testBaseline();
        global.set(SHARED_TEST_KEY, shared);
    }

    const refreshCycleId = msg.payload?.refresh_cycle_id;
    const testAt = Math.max(
        Date.now(),
        Number(shared.observed_at || 0)
    );
    const now = new Date(testAt).toISOString();

    function testTracker(entityId, state) {
        return {
            entity_id: entityId,
            state,
            attributes: { gps_accuracy: 20 },
            last_changed: now,
            last_updated: now
        };
    }

    const transition = shared.transitions?.people;
    const activeTransition =
        transition?.domain === "people" &&
        transition?.test_case === msg._location_test_case &&
        msg._location_test_reset !== true;

    const source = activeTransition
        ? transition.source
        : "refresh";

    msg.payload = {
        event: activeTransition
            ? "location_update"
            : "context_snapshot",
        source,
        refresh_cycle_id: refreshCycleId,
        trigger_entity: activeTransition
            ? (
                source === "resident_primary"
                    ? "device_tracker.mobile_primary_source_1"
                    : "device_tracker.mobile_secondary_source_1"
            )
            : undefined,
        trigger_state: activeTransition
            ? transition.state
            : undefined,
        trigger_prev_state: activeTransition
            ? transition.prev
            : undefined,
        resident_primary: testTracker(
            "device_tracker.mobile_primary_source_1",
            shared.resident_primary
        ),
        resident_primary_icloud: testTracker(
            "device_tracker.mobile_primary_source_2",
            shared.resident_primary
        ),
        resident_secondary: testTracker(
            "device_tracker.mobile_secondary_source_1",
            shared.resident_secondary
        ),
        resident_secondary_icloud: testTracker(
            "device_tracker.mobile_secondary_source_2",
            shared.resident_secondary
        )
    };
}

/*
 * Durante um teste, somente o estado interno deste normalizador
 * é isolado. As três saídas continuam sendo as saídas normais
 * do fluxo, permitindo ensaiar toda a cadeia posterior.
 */
function contextKey(base) {
    return TEST_MODE ? `${base}__test` : base;
}

function ctxGet(base, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.get(key)
        : flow.get(key, store);
}

function ctxSet(base, value, store) {
    const key = contextKey(base);

    return TEST_MODE || !store
        ? flow.set(key, value)
        : flow.set(key, value, store);
}

/*
 * Impede que unknown/unavailable/null sejam interpretados
 * como origem válida de uma transição real.
 */
function validZoneState(value) {
    return (
        typeof value === "string" &&
        !["", "unknown", "unavailable"].includes(value)
    );
}

function distanceMeters(lat1, lon1, lat2, lon2) {
    const toRad = (value) => value * Math.PI / 180;

    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);

    const a =
        Math.sin(dLat / 2) ** 2 +
        Math.cos(toRad(lat1)) *
        Math.cos(toRad(lat2)) *
        Math.sin(dLon / 2) ** 2;

    return (
        6371000 *
        2 *
        Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
    );
}

function reliableCoords(entity) {
    const attrs = entity?.attributes ?? {};

    const lat = Number(attrs.latitude);
    const lon = Number(attrs.longitude);
    const accuracy = Number(attrs.gps_accuracy);

    const hasCoords =
        Number.isFinite(lat) &&
        Number.isFinite(lon);

    const hasAccuracy = Number.isFinite(accuracy);

    return hasCoords &&
        (!hasAccuracy || accuracy <= MAX_GPS_ACCURACY_M)
        ? { lat, lon }
        : null;
}

function primaryHome(entity) {
    const coords = reliableCoords(entity);

    if (HOME_KNOWN && coords) {
        return (
            distanceMeters(
                HOME_LAT,
                HOME_LON,
                coords.lat,
                coords.lon
            ) <= ARM_DISTANCE_M
        );
    }

    const accuracy = Number(
        entity?.attributes?.gps_accuracy
    );

    if (
        Number.isFinite(accuracy) &&
        accuracy > MAX_GPS_ACCURACY_M
    ) {
        return false;
    }

    return entity?.state === "home";
}

function homeForMs(entity) {
    const changedAt = Date.parse(
        entity?.last_changed ?? ""
    );

    return Number.isFinite(changedAt)
        ? Date.now() - changedAt
        : null;
}

function observedAt(entity) {
    const value = Date.parse(
        entity?.last_updated ??
        entity?.last_changed ??
        ""
    );

    return Number.isFinite(value)
        ? value
        : null;
}

function freshTracker(entity) {
    const value = observedAt(entity);

    return (
        value !== null &&
        value <= Date.now() + FUTURE_TOLERANCE_MS &&
        Date.now() - value <= LOCATION_FRESH_MS
    );
}

const TRACKER_RECENCY_TIE_MS = 60 * 1000;

function trackerAccuracy(entity) {
    const accuracy = Number(
        entity?.attributes?.gps_accuracy
    );

    return Number.isFinite(accuracy) &&
        accuracy >= 0
        ? accuracy
        : Infinity;
}

function mergeTrackers(primary, fallback) {
    const primaryFresh = freshTracker(primary);
    const fallbackFresh = freshTracker(fallback);

    if (primaryFresh !== fallbackFresh) {
        return primaryFresh
            ? primary
            : fallback;
    }

    const primaryCoords = reliableCoords(primary);
    const fallbackCoords = reliableCoords(fallback);

    if (Boolean(primaryCoords) !== Boolean(fallbackCoords)) {
        return primaryCoords
            ? primary
            : fallback;
    }

    const primaryObservedAt = observedAt(primary);
    const fallbackObservedAt = observedAt(fallback);

    if (
        primaryObservedAt !== null &&
        fallbackObservedAt !== null &&
        Math.abs(primaryObservedAt - fallbackObservedAt) >
            TRACKER_RECENCY_TIE_MS
    ) {
        return primaryObservedAt > fallbackObservedAt
            ? primary
            : fallback;
    }

    const primaryAccuracy = trackerAccuracy(primary);
    const fallbackAccuracy = trackerAccuracy(fallback);

    if (primaryAccuracy !== fallbackAccuracy) {
        return primaryAccuracy < fallbackAccuracy
            ? primary
            : fallback;
    }

    if (primaryObservedAt !== fallbackObservedAt) {
        if (primaryObservedAt === null) return fallback;
        if (fallbackObservedAt === null) return primary;

        return primaryObservedAt > fallbackObservedAt
            ? primary
            : fallback;
    }

    const primaryStateValid = validZoneState(
        primary?.state
    );
    const fallbackStateValid = validZoneState(
        fallback?.state
    );

    if (primaryStateValid !== fallbackStateValid) {
        return primaryStateValid
            ? primary
            : fallback;
    }

    return primary ?? fallback;
}

function position(primary, fallback) {
    const selected = mergeTrackers(
        primary,
        fallback
    );

    const attrs = selected?.attributes ?? {};
    const coords = reliableCoords(selected);

    const accuracy = Number(
        attrs.gps_accuracy
    );

    const state = selected?.state;

    const validState =
        typeof state === "string" &&
        ![
            "unknown",
            "unavailable",
            ""
        ].includes(state);

    const updatedAt =
        observedAt(selected);

    const stale =
        updatedAt === null ||
        Date.now() - updatedAt > LOCATION_FRESH_MS ||
        updatedAt > Date.now() + FUTURE_TOLERANCE_MS;

    return {
        entity_id: selected?.entity_id,
        state,

        latitude:
            coords?.lat ?? null,

        longitude:
            coords?.lon ?? null,

        gps_accuracy:
            Number.isFinite(accuracy)
                ? accuracy
                : null,

        location_reliable:
            Boolean(coords),

        state_valid:
            validState &&
            !stale &&
            (
                Boolean(coords) ||
                [
                    "home",
                    "not_home",
                    APPROACH_ZONE
                ].includes(state)
            ),

        updated_at: updatedAt,
        stale,
        ready:
            validState &&
            !stale,

        distance_m:
            HOME_KNOWN && coords
                ? Math.round(
                    distanceMeters(
                        HOME_LAT,
                        HOME_LON,
                        coords.lat,
                        coords.lon
                    )
                )
                : null,

        gate_distance_m:
            GATE_KNOWN && coords
                ? Math.round(
                    distanceMeters(
                        GATE_LAT,
                        GATE_LON,
                        coords.lat,
                        coords.lon
                    )
                )
                : null,

        current_home:
            validState && !stale
                ? primaryHome(selected)
                : null,

        primary_home:
            primaryHome(primary),

        any_tracker_home:
            primaryHome(primary) ||
            primaryHome(fallback),

        primary_home_for_ms:
            homeForMs(primary)
    };
}

function isAway(item) {
    if (item?.ready !== true) {
        return false;
    }

    if (item?.distance_m !== null) {
        return (
            item.distance_m >
            ARM_DISTANCE_M
        );
    }

    return item?.state === "not_home";
}

function isArmingHome(item) {
    if (item?.ready !== true) {
        return false;
    }

    if (item?.distance_m !== null) {
        return (
            item.distance_m <=
            ARM_DISTANCE_M
        );
    }

    if (
        item?.gps_accuracy !== null &&
        item.gps_accuracy >
        MAX_GPS_ACCURACY_M
    ) {
        return false;
    }

    return item?.state === "home";
}

function isArrivalHome(item) {
    if (item?.ready !== true) {
        return false;
    }

    if (
        item?.gate_distance_m !== null &&
        item.gate_distance_m <=
        ARRIVAL_DISTANCE_M
    ) {
        return true;
    }

    if (item?.distance_m !== null) {
        return (
            item.distance_m <=
            ARRIVAL_DISTANCE_M
        );
    }

    if (
        item?.gps_accuracy !== null &&
        item.gps_accuracy >
        MAX_GPS_ACCURACY_M
    ) {
        return false;
    }

    return item?.state === "home";
}

function validObject(value) {
    return (
        value &&
        typeof value === "object" &&
        !Array.isArray(value)
    );
}


/* ================================
 * NORMALIZAÇÃO
 * ================================ */

const resident_primary = position(
    msg.payload?.resident_primary,
    msg.payload?.resident_primary_icloud
);

const resident_secondary = position(
    msg.payload?.resident_secondary,
    msg.payload?.resident_secondary_icloud
);

const people = {
    resident_primary,
    resident_secondary
};

const source =
    msg.payload?.source;

const sourcePosition =
    people[source];

const triggerState =
    msg.payload?.trigger_state;

const triggerPrevState =
    msg.payload?.trigger_prev_state;

const triggerPrevValid =
    validZoneState(
        triggerPrevState
    );

const isLocationEvent =
    msg.payload?.event ===
    "location_update";


/* ================================
 * RECOVERY
 * ================================ */

let recovery =
    ctxGet(
        RECOVERY_KEY,
        PERSISTENT
    );

if (
    !validObject(recovery) ||
    recovery.version !== 1
) {
    if (recovery !== undefined) {
        node.warn(
            "localizacao_pessoas: recovery persistido invalido; descartado"
        );
    }

    recovery = {
        version: 1
    };
}

if (
    !validObject(
        recovery.recent_arrivals
    )
) {
    recovery.recent_arrivals = {};
}

for (
    const [
        itemKey,
        timestamp
    ]
    of Object.entries(
        recovery.recent_arrivals
    )
) {
    if (
        !Number.isFinite(timestamp) ||
        timestamp >
        Date.now() +
        FUTURE_TOLERANCE_MS ||
        Date.now() -
        timestamp >
        DEDUPE_TTL_MS
    ) {
        delete recovery
            .recent_arrivals[
            itemKey
        ];
    }
}


/* ================================
 * ARMAMENTO
 * ================================ */

let armed =
    ctxGet(
        ARMED_KEY
    );

if (!validObject(armed)) {
    armed =
        validObject(
            recovery
                .arrival_armed
        )
            ? recovery
                .arrival_armed
            : {};
}

armed = {
    resident_primary:
        armed.resident_primary === true,

    resident_secondary:
        armed.resident_secondary === true
};

for (
    const [
        name,
        item
    ]
    of Object.entries(
        people
    )
) {
    if (isAway(item)) {
        armed[name] = true;
    }
}


/* ================================
 * DETECÇÃO DE CHEGADA
 * ================================ */

let arrival = null;
let lightingOnlyArrival = null;

if (
    isLocationEvent &&
    sourcePosition?.ready ===
    true &&
    triggerPrevValid
) {
    const approachEntry =
        triggerState ===
        APPROACH_ZONE &&
        triggerPrevState ===
        "not_home" &&
        sourcePosition
            .any_tracker_home !==
        true;

    const leavingHome =
        triggerPrevState ===
        "home";

    const staleCatchUp =
        !approachEntry &&
        sourcePosition
            .primary_home ===
        true &&
        typeof sourcePosition
            .primary_home_for_ms ===
        "number" &&
        sourcePosition
            .primary_home_for_ms >
        PRIMARY_HOME_GRACE_MS;

    if (
        !leavingHome &&
        !staleCatchUp &&
        (
            approachEntry ||
            isArrivalHome(
                sourcePosition
            )
        ) &&
        armed[source]
    ) {
        arrival = {
            _location_test:
                TEST_MODE,

            _location_test_case:
                TEST_MODE
                    ? (msg._location_test_case ?? null)
                    : undefined,

            payload: {
                contract:
                    "security.arrival.v1",

                kind:
                    "arrival",

                source,

                arriving: [
                    source
                ],

                arrival_source_type:
                    "person",

                arrival_stage:
                    approachEntry
                        ? "approach"
                        : "home",

                arrival_previous_state:
                    triggerPrevState,

                event_at:
                    sourcePosition
                        .updated_at ??
                    Date.now(),

                refresh_cycle_id:
                    msg.payload?.refresh_cycle_id
            }
        };
    }

    if (
        !approachEntry &&
        isArrivalHome(
            sourcePosition
        )
    ) {
        armed[source] =
            false;
    }
}


/*
 * Exceção estrita da iluminação: unknown/unavailable → chegando pode indicar que o
 * tracker recuperou diretamente já dentro da zona. Não publica na saída de
 * chegada geral (alarme); o gate físico posterior ainda exige motor ON atual.
 */
if (
    isLocationEvent &&
    sourcePosition?.ready === true &&
    triggerState === APPROACH_ZONE &&
    ["unknown", "unavailable"].includes(triggerPrevState) &&
    sourcePosition.any_tracker_home !== true
) {
    lightingOnlyArrival = {
        _location_test: TEST_MODE,
        _location_test_case: TEST_MODE
            ? (msg._location_test_case ?? null)
            : undefined,
        payload: {
            contract: "security.arrival.v1",
            kind: "arrival",
            source,
            arriving: [source],
            arrival_source_type: "person",
            arrival_stage: "approach",
            arrival_previous_state: triggerPrevState,
            illumination_only: true,
            event_at: sourcePosition.updated_at ?? Date.now(),
            refresh_cycle_id: msg.payload?.refresh_cycle_id
        }
    };
}

/* ================================
 * SNAPSHOT / REFRESH
 * ================================ */

if (!isLocationEvent) {
    for (
        const [
            name,
            item
        ]
        of Object.entries(
            people
        )
    ) {
        if (
            isArmingHome(
                item
            )
        ) {
            armed[name] =
                false;
        }
    }
}


/* ================================
 * DEDUPE CHEGADA
 * ================================ */

if (arrival) {
    const eventAt =
        sourcePosition
            ?.updated_at ??
        Date.now();

    const key =
        [
            source,
            arrival.payload
                .arrival_stage,
            triggerState ??
            "?",
            eventAt
        ].join(":");

    if (
        recovery
            .recent_arrivals[
        key
        ]
    ) {
        arrival = null;
    } else {
        recovery
            .recent_arrivals[
            key
        ] =
            Date.now();
    }
}


if (lightingOnlyArrival) {
    const eventAt = sourcePosition?.updated_at ?? Date.now();
    const key = [
        "lighting_tracker_recovery_approach",
        source,
        eventAt
    ].join(":");

    if (recovery.recent_arrivals[key]) {
        lightingOnlyArrival = null;
    } else {
        recovery.recent_arrivals[key] = Date.now();
    }
}

/* ================================
 * PERSISTÊNCIA
 * ================================ */

ctxSet(
    ARMED_KEY,
    armed
);

recovery.arrival_armed = {
    ...armed
};

recovery.updated_at =
    Date.now();

ctxSet(
    RECOVERY_KEY,
    recovery,
    PERSISTENT
);


/* ================================
 * PEOPLE CONTEXT
 * ================================ */

const distances =
    Object.values(
        people
    )
        .map(
            (item) =>
                item.distance_m
        )
        .filter(
            (value) =>
                value !== null
        );

const peopleContext = {
    resident_primary,
    resident_secondary,

    anyone_away:
        resident_primary.ready &&
            resident_secondary.ready
            ? Object.values(
                people
            ).some(
                isAway
            )
            : null,

    nearest_distance_m:
        distances.length
            ? Math.min(
                ...distances
            )
            : null,

    state_valid:
        resident_primary.state_valid &&
        resident_secondary.state_valid,

    ready:
        resident_primary.ready &&
        resident_secondary.ready,

    stale:
        resident_primary.stale ||
        resident_secondary.stale,

    updated_at:
        Math.max(
            ...[
                resident_primary.updated_at,
                resident_secondary.updated_at
            ].filter(
                Number.isFinite
            ),
            0
        ),

    arrival_armed: {
        ...armed
    }
};

ctxSet(
    "people_context_v1",
    peopleContext
);

const previousReady =
    ctxGet(
        "security_people_ready_logged"
    );

if (
    previousReady !==
    peopleContext.ready
) {
    node.log?.(
        "localizacao_pessoas: contexto " +
        (
            peopleContext.ready
                ? "ready"
                : "pending/stale"
        )
    );

    ctxSet(
        "security_people_ready_logged",
        peopleContext.ready
    );
}


/* ================================
 * OUTPUT 1 - CONTEXTO
 * ================================ */

msg.payload = {
    contract:
        "security.people-context.v1",

    kind:
        "people_context",

    context:
        peopleContext,

    trigger_entity:
        msg.payload
            ?.trigger_entity,

    trigger_state:
        triggerState,

    trigger_prev_state:
        triggerPrevState,

    confirmed_home_transition:
        isLocationEvent &&
        sourcePosition?.ready ===
        true &&
        triggerPrevValid &&
        triggerState ===
        "home" &&
        triggerPrevState !==
        "home",

    refresh_cycle_id:
        msg.payload
            ?.refresh_cycle_id,

    updated_at:
        peopleContext.updated_at,

    valid:
        peopleContext.state_valid,

    ready:
        peopleContext.ready,

    stale:
        peopleContext.stale,

    source:
        source ??
        "people",

    reason:
        peopleContext.ready
            ? "current_entities"
            : "entity_stale_or_unavailable"
};


/*
 * A identificação de teste acompanha as mensagens,
 * mas NÃO muda o roteamento das três saídas.
 */
if (TEST_MODE) {
    msg.payload.test_mode =
        true;

    msg.payload.test_case =
        msg._location_test_case ??
        null;

    if (arrival?.payload) {
        arrival.payload.test_mode =
            true;

        arrival.payload.test_case =
            msg._location_test_case ??
            null;
    }
}


/*
 * OUTPUT 1 = contexto normal
 * OUTPUT 2 = chegada geral
 * OUTPUT 3 = unknown/unavailable → chegando somente para iluminação
 */
return [msg, arrival, lightingOnlyArrival];

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

if (TEST_MODE) {
    node.status({
        fill: "blue",
        shape: "dot",
        text: "TESTE: refresh físico dos iPhones suprimido"
    });
    return null;
}

if (msg.payload?.kind !== "refresh_command") return null;

const peopleContext = flow.get("people_context_v1") ?? {};
const contextReady = peopleContext.ready === true;
const recoveryNeeded =
    msg.payload?.people_ready === false ||
    contextReady !== true;
const anyoneAway = msg.payload.anyone_away === true;

/* Se o próprio contexto está stale, o refresh é o mecanismo de recuperação. */
if (!recoveryNeeded && !anyoneAway) {
    node.status({ fill: "grey", shape: "ring", text: "iPhones ready e todos em casa" });
    return null;
}

const interval = recoveryNeeded
    ? 30 * 1000
    : (
        peopleContext.nearest_distance_m !== null &&
        peopleContext.nearest_distance_m !== undefined &&
        peopleContext.nearest_distance_m <= 2000
            ? 30 * 1000
            : 60 * 1000
    );

const key = "security_people_last_refresh_at";
let last = Number(flow.get(key, "persistent") ?? 0);
const now = Date.now();
if (!Number.isFinite(last) || last > now + 60 * 1000) last = 0;

if (now - last < interval) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "refresh iPhones em cooldown"
    });
    return null;
}

flow.set(key, now, "persistent");
msg.payload.origin = msg.payload.origin ?? "contexto_chegadas";
msg.payload.people_refresh_recovery = recoveryNeeded;

node.status({
    fill: "green",
    shape: "dot",
    text: recoveryNeeded
        ? "refresh iPhones: recuperar readiness"
        : "refresh iPhones: pessoas fora"
});

return msg;

const message = String(msg.error?.message ?? "");
const transient =
    message.includes("Connection lost") ||
    message.includes("NoConnectionError");

if (transient) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "HA reconectando; refresh preservado"
    });
    return null;
}

node.error(
    "Falha inesperada ao solicitar localização: " +
    (message || "erro sem mensagem"),
    msg
);
return null;

const SHARED_TEST_KEY = "security_location_test_state_v1";

const TEST_KEYS = [
    "security_people_recovery_v1__test",
    "people_arrival_armed__test",
    "resident_secondary_approaching_resident_primary_notified__test",
    "resident_secondary_approaching_confirmed_away_cycle__test",
    "people_context_v1__test",
    "security_people_ready_logged__test",
    "security_people_test_clock"
];

const CASES = {
    resident_primary_away: { source: "resident_primary", state: "not_home", prev: "home" },
    resident_primary_approach: { source: "resident_primary", state: "chegando", prev: "not_home" },
    resident_primary_home: { source: "resident_primary", state: "home", prev: "chegando" },
    resident_secondary_away: { source: "resident_secondary", state: "not_home", prev: "home" },
    resident_secondary_approach: { source: "resident_secondary", state: "chegando", prev: "not_home" },
    resident_secondary_home: { source: "resident_secondary", state: "home", prev: "chegando" },
    resident_primary_invalid_home: { source: "resident_primary", state: "home", prev: "unknown" },
    resident_secondary_invalid_approach: { source: "resident_secondary", state: "chegando", prev: "unavailable" },
    resident_primary_unknown_approach: { source: "resident_primary", state: "chegando", prev: "unknown" },
    resident_secondary_unknown_approach: { source: "resident_secondary", state: "chegando", prev: "unknown" },
    resident_primary_unavailable_approach: { source: "resident_primary", state: "chegando", prev: "unavailable" }
};

function baseline(now = Date.now()) {
    return {
        version: 1,
        resident_primary: "home",
        resident_secondary: "home",
        vehicle_primary: "home",
        vehicle_primary_engine: "off",
        vehicle_primary_lock: "locked",
        observed_at: now,
        transitions: {}
    };
}

if (msg.test_case === "reset") {
    const now = Date.now();
    const resetState = baseline(now);
    resetState.reset_at = now;
    global.set(SHARED_TEST_KEY, resetState);

    for (const key of TEST_KEYS) {
        flow.set(key, undefined);
    }

    msg._location_test = true;
    msg._location_test_case = "reset";
    msg._location_test_reset = true;
    msg.payload = {
        kind: "test_reset",
        test_mode: true,
        test_case: "reset"
    };
    msg.topic = "security_context_refresh_test";

    node.status({
        fill: "blue",
        shape: "dot",
        text: "teste compartilhado resetado"
    });

    return msg;
}

const scenarioCases = new Set([
    "scenario_car_away",
    "scenario_car_approach",
    "scenario_car_home"
]);

const test = CASES[msg.test_case];
if (!test && !scenarioCases.has(msg.test_case)) {
    node.warn(
        "Caso de teste de localização desconhecido: " +
        String(msg.test_case)
    );
    return null;
}

let state = global.get(SHARED_TEST_KEY);
if (!state || state.version !== 1) {
    state = baseline();
}

const now = Math.max(
    Date.now(),
    Number(state.observed_at || 0) + 1
);

/*
 * Casos individuais alteram somente a pessoa escolhida.
 * Os cenários combinados alteram resident_secondary + vehicle_primary de forma atômica.
 */
if (msg.test_case === "scenario_car_away") {
    state.resident_secondary = "not_home";
    state.vehicle_primary = "not_home";
    state.vehicle_primary_engine = "on";
    state.vehicle_primary_lock = "locked";
    /* Snapshot away já arma ambos sem fabricar uma chegada. */
    state.transitions = {};
} else if (msg.test_case === "scenario_car_approach") {
    state.resident_secondary = "chegando";
    state.vehicle_primary = "chegando";
    state.vehicle_primary_engine = "on";
    state.vehicle_primary_lock = "locked";
    state.transitions = {
        people: {
            domain: "people",
            source: "resident_secondary",
            state: "chegando",
            prev: "not_home",
            test_case: msg.test_case,
            at: now
        },
        vehicle_primary: {
            domain: "vehicle_primary",
            source: "vehicle_primary",
            state: "chegando",
            prev: "not_home",
            test_case: msg.test_case,
            at: now
        }
    };
} else if (msg.test_case === "scenario_car_home") {
    state.resident_secondary = "home";
    state.vehicle_primary = "home";
    /* Motor ainda ligado: representa chegada antes de desligar/destravar. */
    state.vehicle_primary_engine = "on";
    state.vehicle_primary_lock = "locked";
    state.transitions = {
        people: {
            domain: "people",
            source: "resident_secondary",
            state: "home",
            prev: "chegando",
            test_case: msg.test_case,
            at: now
        },
        vehicle_primary: {
            domain: "vehicle_primary",
            source: "vehicle_primary",
            state: "home",
            prev: "chegando",
            test_case: msg.test_case,
            at: now
        }
    };
} else {
    state[test.source] = test.state;
    state.transitions = {
        people: {
            domain: "people",
            source: test.source,
            state: test.state,
            prev: test.prev,
            test_case: msg.test_case,
            at: now
        }
    };
}

state.observed_at = now;
global.set(SHARED_TEST_KEY, state);

msg._location_test = true;
msg._location_test_case = msg.test_case;
msg.payload = {
    kind: "refresh_tick",
    test_mode: true,
    test_case: msg.test_case,
    test_state: {
        resident_primary: state.resident_primary,
        resident_secondary: state.resident_secondary,
        vehicle_primary: state.vehicle_primary,
        vehicle_primary_engine: state.vehicle_primary_engine,
        vehicle_primary_lock: state.vehicle_primary_lock
    }
};
msg.topic = "security_context_refresh_test";

node.status({
    fill: "green",
    shape: "dot",
    text: scenarioCases.has(msg.test_case)
        ? `cenário: resident_secondary=${state.resident_secondary} | vehicle_primary=${state.vehicle_primary}`
        : `${test.source}: ${test.prev} → ${test.state} | vehicle_primary=${state.vehicle_primary}`
});

return msg;

const HOME_LAT = Number(env.get("HOME_LAT"));
const HOME_LON = Number(env.get("HOME_LON"));
const GATE_LAT = Number(env.get("GATE_LAT"));
const GATE_LON = Number(env.get("GATE_LON"));
const HOME_KNOWN = Number.isFinite(HOME_LAT) && Number.isFinite(HOME_LON);
const GATE_KNOWN = Number.isFinite(GATE_LAT) && Number.isFinite(GATE_LON);
const ARM_DISTANCE_M = 100;
const ARRIVAL_DISTANCE_M = 300;
const MAX_GPS_ACCURACY_M = 100;
const MOVEMENT_THRESHOLD_M = 250;
const APPROACH_ZONE = "chegando";
const PRIMARY_HOME_GRACE_MS = 10 * 60 * 1000;
const LOCATION_FRESH_MS = 30 * 60 * 1000;
const SIGNAL_FRESH_MS = 5 * 60 * 1000;
const RECOVERY_TTL_MS = 24 * 60 * 60 * 1000;
const FUTURE_TOLERANCE_MS = 60 * 1000;
const RECOVERY_KEY = "security_vehicle_primary_recovery_v1";
const PERSISTENT = "persistent";
const ARMED_KEY = "vehicle_primary_arrival_armed";
const IN_USE_KEY = "vehicle_primary_in_use";
const LOCATION_OBSERVATION_KEY = "vehicle_primary_location_observation_v1";


const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const SHARED_TEST_KEY = "security_location_test_state_v1";

function testBaseline(now = Date.now()) {
    return {
        version: 1,
        resident_primary: "home",
        resident_secondary: "home",
        vehicle_primary: "home",
        vehicle_primary_engine: "off",
        vehicle_primary_lock: "locked",
        observed_at: now,
        transitions: {}
    };
}

function clearvehicle_primaryTestState() {
    [
        "security_vehicle_primary_recovery_v1__test",
        "vehicle_primary_arrival_armed__test",
        "vehicle_primary_in_use__test",
        "vehicle_primary_context_v1__test",
        "security_vehicle_primary_recovery_logged__test",
        "security_vehicle_primary_ready_logged__test",
        "vehicle_primary_location_observation_v1__test",
        "security_vehicle_primary_test_clock",
        "security_vehicle_primary_refresh_v1__test",
        "security_vehicle_primary_refresh_v1__test"
    ].forEach((key) => flow.set(key, undefined));
}

if (
    TEST_MODE &&
    msg.payload?.event === "context_snapshot"
) {
    if (msg._location_test_reset === true) {
        clearvehicle_primaryTestState();
    }

    let shared = global.get(SHARED_TEST_KEY);
    if (!shared || shared.version !== 1) {
        shared = testBaseline();
        global.set(SHARED_TEST_KEY, shared);
    }

    const refreshCycleId = msg.payload?.refresh_cycle_id;
    const testAt = Math.max(
        Date.now(),
        Number(shared.observed_at || 0)
    );
    const now = new Date(testAt).toISOString();

    function testEntity(entityId, state, attributes = {}) {
        return {
            entity_id: entityId,
            state,
            attributes,
            last_changed: now,
            last_updated: now
        };
    }

    const transition = shared.transitions?.vehicle_primary;
    const activeTransition =
        transition?.domain === "vehicle_primary" &&
        transition?.test_case === msg._location_test_case &&
        msg._location_test_reset !== true;

    msg.payload = {
        event: activeTransition
            ? "location_update"
            : "context_snapshot",
        source: activeTransition ? "vehicle_primary" : "refresh",
        refresh_cycle_id: refreshCycleId,
        trigger_entity: activeTransition
            ? "device_tracker.vehicle_primary"
            : undefined,
        trigger_state: activeTransition
            ? transition.state
            : undefined,
        trigger_prev_state: activeTransition
            ? transition.prev
            : undefined,
        vehicle_primary: testEntity(
            "device_tracker.vehicle_primary",
            shared.vehicle_primary,
            { gps_accuracy: 20 }
        ),
        vehicle_primary_engine: testEntity(
            "binary_sensor.vehicle_primary_engine",
            shared.vehicle_primary_engine
        ),
        vehicle_primary_lock: testEntity(
            "lock.vehicle_primary_door_lock",
            shared.vehicle_primary_lock
        ),
        vehicle_primary_last_updated: testEntity(
            "sensor.vehicle_primary_last_updated_at",
            now
        )
    };
}

function contextKey(base) {
    return TEST_MODE ? `${base}__test` : base;
}

function ctxGet(base, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.get(key)
        : flow.get(key, store);
}

function ctxSet(base, value, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.set(key, value)
        : flow.set(key, value, store);
}

function validZoneState(value) {
    return (
        typeof value === "string" &&
        !["", "unknown", "unavailable"].includes(value)
    );
}

function distanceMeters(lat1, lon1, lat2, lon2) {
    const toRad = (value) => value * Math.PI / 180;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
    return 6371000 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
function reliableCoords(entity) {
    const attrs = entity?.attributes ?? {};
    const lat = Number(attrs.latitude);
    const lon = Number(attrs.longitude);
    const accuracy = Number(attrs.gps_accuracy);
    const hasCoords = Number.isFinite(lat) && Number.isFinite(lon);
    const hasAccuracy = Number.isFinite(accuracy);
    return hasCoords && (!hasAccuracy || accuracy <= MAX_GPS_ACCURACY_M) ? { lat, lon } : null;
}
function primaryHome(entity) {
    const coords = reliableCoords(entity);
    if (HOME_KNOWN && coords) return distanceMeters(HOME_LAT, HOME_LON, coords.lat, coords.lon) <= ARM_DISTANCE_M;
    const accuracy = Number(entity?.attributes?.gps_accuracy);
    if (Number.isFinite(accuracy) && accuracy > MAX_GPS_ACCURACY_M) return false;
    return entity?.state === "home";
}
function homeForMs(entity) {
    const changedAt = Date.parse(entity?.last_changed ?? "");
    return Number.isFinite(changedAt) ? Date.now() - changedAt : null;
}
function observedAt(entity) {
    const value = Date.parse(entity?.last_updated ?? entity?.last_changed ?? "");
    return Number.isFinite(value) ? value : null;
}
function fresh(entity, ttl) {
    const value = observedAt(entity);
    return value !== null && value <= Date.now() + FUTURE_TOLERANCE_MS && Date.now() - value <= ttl;
}
function position(entity) {
    const attrs = entity?.attributes ?? {};
    const coords = reliableCoords(entity);
    const accuracy = Number(attrs.gps_accuracy);
    const state = entity?.state;
    const validState = typeof state === "string" && !["unknown", "unavailable", ""].includes(state);
    const updatedAt = observedAt(entity);
    const stale = !fresh(entity, LOCATION_FRESH_MS);
    return {
        entity_id: entity?.entity_id, state,
        latitude: coords?.lat ?? null, longitude: coords?.lon ?? null,
        gps_accuracy: Number.isFinite(accuracy) ? accuracy : null,
        location_reliable: Boolean(coords),
        state_valid: validState && !stale && (Boolean(coords) || ["home", "not_home", APPROACH_ZONE].includes(state)),
        updated_at: updatedAt, stale, ready: validState && !stale,
        distance_m: HOME_KNOWN && coords ? Math.round(distanceMeters(HOME_LAT, HOME_LON, coords.lat, coords.lon)) : null,
        gate_distance_m: GATE_KNOWN && coords ? Math.round(distanceMeters(GATE_LAT, GATE_LON, coords.lat, coords.lon)) : null,
        primary_home: primaryHome(entity), primary_home_for_ms: homeForMs(entity),
    };
}
function isAway(item) {
    if (item?.ready !== true) return false;
    if (item?.distance_m !== null) return item.distance_m > ARM_DISTANCE_M;
    return item?.state === "not_home";
}
function isArmingHome(item) {
    if (item?.ready !== true) return false;
    if (item?.distance_m !== null) return item.distance_m <= ARM_DISTANCE_M;
    if (item?.gps_accuracy !== null && item.gps_accuracy > MAX_GPS_ACCURACY_M) return false;
    return item?.state === "home";
}
function isArrivalHome(item) {
    if (item?.ready !== true) return false;
    if (item?.gate_distance_m !== null && item.gate_distance_m <= ARRIVAL_DISTANCE_M) return true;
    if (item?.distance_m !== null) return item.distance_m <= ARRIVAL_DISTANCE_M;
    if (item?.gps_accuracy !== null && item.gps_accuracy > MAX_GPS_ACCURACY_M) return false;
    return item?.state === "home";
}


function semanticTimestamp(entity) {
    const value = Date.parse(entity?.state ?? "");
    return Number.isFinite(value) ? value : null;
}

const vehicle_primary = position(msg.payload?.vehicle_primary);
const telemetryUpdatedAt = semanticTimestamp(
    msg.payload?.vehicle_primary_last_updated
);
const engineState = msg.payload?.vehicle_primary_engine?.state;
const lockState = msg.payload?.vehicle_primary_lock?.state;
const engineFresh = fresh(msg.payload?.vehicle_primary_engine, SIGNAL_FRESH_MS);
const lockFresh = fresh(msg.payload?.vehicle_primary_lock, SIGNAL_FRESH_MS);
const engineOn = engineFresh && ["on", "running"].includes(engineState);
const engineOff = engineFresh && ["off", "stopped", "idle"].includes(engineState);
const unlocked = lockFresh && lockState === "unlocked";

const isLocationEvent = msg.payload?.event === "location_update";
const triggerState = msg.payload?.trigger_state;
const triggerPrevState = msg.payload?.trigger_prev_state;
const triggerPrevValid = validZoneState(triggerPrevState);
const previousLocation =
    ctxGet(LOCATION_OBSERVATION_KEY, PERSISTENT);
const zoneChanged =
    triggerPrevValid &&
    triggerState !== triggerPrevState &&
    ["home", "not_home", APPROACH_ZONE].includes(triggerState);
const movementDistanceM =
    previousLocation &&
    Number.isFinite(previousLocation.latitude) &&
    Number.isFinite(previousLocation.longitude) &&
    Number.isFinite(vehicle_primary.latitude) &&
    Number.isFinite(vehicle_primary.longitude)
        ? distanceMeters(
            previousLocation.latitude,
            previousLocation.longitude,
            vehicle_primary.latitude,
            vehicle_primary.longitude
        )
        : null;
const movementAccuracyM = Math.max(
    MOVEMENT_THRESHOLD_M,
    Number(previousLocation?.gps_accuracy || 0) +
        Number(vehicle_primary.gps_accuracy || 0)
);
const significantCoordinateMovement =
    Number.isFinite(movementDistanceM) &&
    movementDistanceM >= movementAccuracyM &&
    Number(vehicle_primary.updated_at || 0) >
        Number(previousLocation?.updated_at || 0);
const freshVehicleMovement =
    isLocationEvent &&
    vehicle_primary.ready === true &&
    (zoneChanged || significantCoordinateMovement);

if (
    isLocationEvent &&
    vehicle_primary.location_reliable === true &&
    (
        !previousLocation ||
        zoneChanged ||
        significantCoordinateMovement
    )
) {
    ctxSet(
        LOCATION_OBSERVATION_KEY,
        {
            version: 1,
            latitude: vehicle_primary.latitude,
            longitude: vehicle_primary.longitude,
            gps_accuracy: vehicle_primary.gps_accuracy,
            state: vehicle_primary.state,
            updated_at: vehicle_primary.updated_at
        },
        PERSISTENT
    );
}

if (!TEST_MODE && freshVehicleMovement) {
    const movementKind = zoneChanged ? "zone" : "distance";
    const distanceBucketM = Number.isFinite(movementDistanceM)
        ? Math.ceil(movementDistanceM / 100) * 100
        : null;
    node.log?.(
        "VEHICLE_PRIMARY_LOCATION_CHANGED kind=" + movementKind +
        (distanceBucketM === null
            ? ""
            : " displacement_bucket_m=" + distanceBucketM)
