    const waitS = Math.max(1, Math.ceil((state.next_allowed_at - now) / 1000));
    const waitingEvidence = state.awaiting_evidence === true;
    save(waitingEvidence ? "backoff" : "cooldown", requestedReason, {
        enabled: true
    });
    node.status({
        fill: "grey",
        shape: "ring",
        text: waitingEvidence
            ? `retry Bluelink em ${waitS}s`
            : `refresh vehicle_primary cooldown ${waitS}s`
    });
    if (waitingEvidence) {
        return blockedNotification("backoff", waitS);
    }
    return blockedNotification("minimum_interval", waitS);
}

state.baseline_observed_at = {
    telemetry: Number(vehicleContext.telemetry_updated_at ?? 0)
};
state.attempts = Math.min(5, state.attempts + 1);
state.last_attempt_at = now;
state.last_request_at = now;
state.next_allowed_at = now + selectedIntervalMs;
state.awaiting_evidence = true;
state.request_in_flight = true;
state.in_flight_until = now + IN_FLIGHT_LEASE_MS;
state.last_attempt_cycle = msg.payload.refresh_cycle_id ?? null;
state.require_lighting_ready = requireLightingReady;
state.recovery_reason = requestedReason;
state.manual_force = requestedReason === "manual_force";
let failureNotification = null;
if (state.attempts >= 2 && !state.failure_notified_at) {
    state.failure_notified_at = now;
    state.last_failure_class = state.last_failure_class ?? "no_fresh_data";
    failureNotification = {
        ...msg,
        payload: (msg.payload && typeof msg.payload === "object")
            ? { ...msg.payload }
            : msg.payload
    };
    failureNotification.payload = {
        ...failureNotification.payload,
        test_mode: TEST_MODE,
        side_effect: "notify:resident_primary"
    };
    failureNotification.alert = {
        title: TEST_MODE
            ? "TESTE — Falha ao atualizar veículo"
            : "Falha ao atualizar veículo",
        message:
            "O Bluelink não publicou dados novos após a atualização. " +
            "As retentativas automáticas continuam com backoff; " +
            "verifique a conectividade do veículo e o serviço da Hyundai."
    };
}
save("refreshing", requestedReason, { enabled: true });

node.log?.(
    (state.attempts > 1
        ? "VEHICLE_PRIMARY_REFRESH_RETRY"
        : "VEHICLE_PRIMARY_REFRESH_REQUESTED") +
    " attempt=" + state.attempts +
    " reason=" + requestedReason +
    " recovery=" + String(recoveryNeeded) +
    " interval_minutes=" + String(selectedIntervalMs / 60_000) +
    " both_home=" + String(bothResidentsHome) +
    " require_lighting_ready=" + String(requireLightingReady) +
    " test_mode=" + String(TEST_MODE)
);

msg.payload.retry_attempt = state.attempts;
msg.payload.refresh_requested_at = now;
msg.payload.vehicle_primary_refresh_recovery = recoveryNeeded;
msg.payload.require_lighting_ready = requireLightingReady;
msg.payload.origin = msg.payload.origin ?? "contexto_chegadas";
msg.payload.test_mode = TEST_MODE;

node.status({
    fill: TEST_MODE ? "blue" : (recoveryNeeded ? "yellow" : "green"),
    shape: "dot",
    text: TEST_MODE
        ? `TESTE Bluelink #${state.attempts}: dry-run`
        : (recoveryNeeded
            ? `Bluelink #${state.attempts}: ${requestedReason}`
            : `Bluelink #${state.attempts}: refresh real`)
});

return [msg, TEST_MODE ? null : msg, null, failureNotification];

if (
    msg.payload?.kind !== "arrival" ||
    msg.payload?.arrival_source_type !== "vehicle_primary"
) return null;

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;
const key = TEST_MODE
    ? "security_vehicle_primary_trip_action_v1__test"
    : "security_vehicle_primary_trip_action_v1";
const previous = TEST_MODE ? flow.get(key) : flow.get(key, "persistent");
const now = Number(msg.payload?.test_now) || Date.now();
const eventKey = [
    msg.payload.source,
    msg.payload.arrival_stage,
    msg.payload.event_at ?? msg.payload.trigger_state ?? "?"
].join(":");
const previousAt = Number(previous?.at ?? 0);
if (
    previous?.event_key === eventKey &&
    previousAt <= now + 60 * 1000 &&
    now - previousAt < 10 * 60 * 1000
) return null;

const record = { version: 2, event_key: eventKey, at: now };
if (TEST_MODE) flow.set(key, record);
else flow.set(key, record, "persistent");

let wake = null;
if (msg.payload.request_vehicle_primary_wake === true) {
    wake = structuredClone(msg);
    wake.payload = {
        ...wake.payload,
        contract: "security.refresh-command.v1",
        kind: "refresh_command",
        reason: "vehicle_primary_arrival",
        recovery_needed: true,
        force_recovery: true,
        require_lighting_ready: true,
        test_mode: TEST_MODE,
        issued_at: now
    };
}

const trip = structuredClone(msg);
trip.payload = {
    ...trip.payload,
    side_effect: "vehicle_primary.refresh_trip_info",
    test_mode: TEST_MODE
};

return [wake, trip];

/*
 * O retorno de button.press significa apenas que o serviço foi aceito.
 * NÃO é evidência de que Bluelink atualizou as entidades.
 * Após o delay, inicia outro snapshot coordenado.
 */
msg._location_test = false;
delete msg._location_test_case;
msg.payload = {
    kind: "refresh_tick",
    origin: "contexto_vehicle_primary",
    reason: "post_bluelink_recheck",
    requested_at: Date.now()
};
node.status({ fill: "blue", shape: "dot", text: "rechecando entidades após Bluelink" });
return msg;

const SHARED_TEST_KEY = "security_location_test_state_v1";

const TEST_KEYS = [
    "security_vehicle_primary_recovery_v1__test",
    "vehicle_primary_arrival_armed__test",
    "vehicle_primary_in_use__test",
    "vehicle_primary_context_v1__test",
    "security_vehicle_primary_recovery_logged__test",
    "security_vehicle_primary_ready_logged__test",
    "security_vehicle_primary_test_clock"
];

const CASES = {
    vehicle_primary_engine_on: { engine: "on" },
    vehicle_primary_engine_off: { engine: "off" },
    vehicle_primary_away: { state: "not_home", prev: "home" },
    vehicle_primary_approach: { state: "chegando", prev: "not_home" },
    vehicle_primary_home: { state: "home", prev: "chegando" },
    vehicle_primary_invalid_home: { state: "home", prev: "unknown" },
    vehicle_primary_invalid_approach: { state: "chegando", prev: "unavailable" }
};

function baseline(now = Date.now()) {
    return {
        version: 1,
        resident_primary: "home",
        resident_secondary: "home",
        vehicle_primary: "home",
        vehicle_primary_engine: "off",
        vehicle_primary_lock: "locked",
        observed_at: now,
        transitions: {}
    };
}

if (msg.test_case === "reset") {
    const now = Date.now();
    const resetState = baseline(now);
    resetState.reset_at = now;
    global.set(SHARED_TEST_KEY, resetState);

    for (const key of TEST_KEYS) {
        flow.set(key, undefined);
    }

    msg._location_test = true;
    msg._location_test_case = "reset";
    msg._location_test_reset = true;
    msg.payload = {
        kind: "test_reset",
        test_mode: true,
        test_case: "reset"
    };
    msg.topic = "security_context_refresh_test";

    node.status({
        fill: "blue",
        shape: "dot",
        text: "teste compartilhado resetado | motor=OFF"
    });

    return msg;
}

const test = CASES[msg.test_case];
if (!test) {
    node.warn(
        "Caso de teste do vehicle_primary desconhecido: " +
        String(msg.test_case)
    );
    return null;
}

let state = global.get(SHARED_TEST_KEY);
if (!state || state.version !== 1) {
    state = baseline();
}

const now = Math.max(
    Date.now(),
    Number(state.observed_at || 0) + 1
);

/*
 * Estado sintético cumulativo:
 * - ON/OFF altera somente o motor;
 * - os passos de localização preservam o motor escolhido;
 * - pessoas e trava também são preservadas.
 */
if (Object.hasOwn(test, "state")) {
    state.vehicle_primary = test.state;
}
if (Object.hasOwn(test, "engine")) {
    state.vehicle_primary_engine = test.engine;
}
state.observed_at = now;
state.transitions = Object.hasOwn(test, "state")
    ? {
        vehicle_primary: {
            domain: "vehicle_primary",
            source: "vehicle_primary",
            state: test.state,
            prev: test.prev,
            test_case: msg.test_case,
            at: now
        }
    }
    : {};

global.set(SHARED_TEST_KEY, state);

msg._location_test = true;
msg._location_test_case = msg.test_case;
msg.payload = {
    kind: "refresh_tick",
    test_mode: true,
    test_case: msg.test_case,
    test_state: {
        resident_primary: state.resident_primary,
        resident_secondary: state.resident_secondary,
        vehicle_primary: state.vehicle_primary,
        vehicle_primary_engine: state.vehicle_primary_engine,
        vehicle_primary_lock: state.vehicle_primary_lock
    }
};
msg.topic = "security_context_refresh_test";

const locationText = Object.hasOwn(test, "state")
    ? test.prev + " → " + test.state
    : "localização=" + state.vehicle_primary;

node.status({
    fill: state.vehicle_primary_engine === "on" ? "green" : "grey",
    shape: "dot",
    text:
        "vehicle_primary: " + locationText +
        " | motor=" + state.vehicle_primary_engine.toUpperCase()
});

return msg;

const source = String(msg.error?.source?.name ?? "unknown")
    .replace(/[^a-zA-Z0-9 _-]/g, "");
const message = String(msg.error?.message ?? "unknown")
    .replace(/[\r\n]+/g, " ")
    .slice(0, 240);
const failureClass = /(?:401|unauthori[sz]ed|authentic)/i.test(message)
    ? "authentication"
    : /(?:timeout|timed out|readtimeout)/i.test(message)
        ? "timeout"
        : /already in progress|coalesced/i.test(message)
            ? "concurrent_request_coalesced"
            : "api_error";
const key = "security_vehicle_primary_refresh_v1";
const state = flow.get(key, "persistent") ?? {};
const now = Date.now();
state.request_in_flight = false;
state.in_flight_until = null;
state.awaiting_evidence = true;
state.state = "backoff";
state.reason = failureClass;
state.failure_at = now;
state.failure_source = source;
state.last_failure_class = failureClass;
state.next_retry_at = Number(state.next_allowed_at ?? 0) || null;
state.cooldown_until = null;
state.updated_at = now;
let notification = null;
if (!Number.isFinite(state.failure_notified_at)) {
    state.failure_notified_at = now;
    msg.payload = {
        ...(msg.payload ?? {}),
        test_mode: false,
        side_effect: "notify:resident_primary"
    };
    msg.alert = {
        title: "Erro ao atualizar veículo",
        message:
            "A atualização do veículo falhou antes de receber novos dados. " +
            "As retentativas automáticas permanecem em backoff; verifique " +
            "a integração Bluelink."
    };
    notification = msg;
}
flow.set(key, state, "persistent");
node.error(
    "VEHICLE_PRIMARY_API_ERROR class=" + failureClass +
    " source=" + source + " message=" + message
);
return notification;

const raw = flow.get("security_vehicle_primary_refresh_v1", "persistent") ?? {};
const now = Date.now();
let state = raw.state ?? "idle";
let deadline = null;

if (
    raw.request_in_flight === true &&
    Number(raw.in_flight_until ?? 0) > now
) {
    deadline = Number(raw.in_flight_until);
    state = "in_flight";
} else if (raw.awaiting_evidence === true) {
    deadline = Number(raw.next_retry_at ?? raw.next_allowed_at ?? 0) || null;
    if (
        !["refreshing", "awaiting_evidence"].includes(state) ||
        now - Number(raw.last_attempt_at ?? 0) >= 30 * 1000
    ) {
        state = "backoff";
    }
} else if (Number(raw.cooldown_until ?? raw.next_allowed_at ?? 0) > now) {
    deadline = Number(raw.cooldown_until ?? raw.next_allowed_at);
    state = "cooldown";
} else if (state === "cooldown") {
    state = "idle";
}

const remainingSeconds = deadline && deadline > now
    ? Math.max(0, Math.ceil((deadline - now) / 1000))
    : 0;
const iso = (value) => Number(value) > 0
    ? new Date(Number(value)).toISOString()
    : null;

const status = {
    state,
    reason: raw.reason ?? raw.recovery_reason ?? null,
    attempt: Number(raw.attempts ?? 0),
    last_request_at: iso(raw.last_request_at ?? raw.last_attempt_at),
    last_success_at: iso(raw.last_success_at),
    next_retry_at: raw.awaiting_evidence === true
        ? iso(raw.next_retry_at ?? raw.next_allowed_at)
        : null,
    cooldown_until: raw.awaiting_evidence !== true
        ? iso(raw.cooldown_until ?? raw.next_allowed_at)
        : null,
    remaining_seconds: remainingSeconds,
    awaiting_evidence: raw.awaiting_evidence === true,
    request_in_flight: raw.request_in_flight === true,
    in_flight_until: raw.request_in_flight === true
        ? iso(raw.in_flight_until)
        : null,
    service_accepted_at: iso(raw.service_accepted_at),
    last_failure_class: raw.last_failure_class ?? null,
    manual_force: raw.manual_force === true,
    updated_at: new Date(now).toISOString()
};

const discovery = {
    name: "Refresh Coordinator",
    unique_id: "vehicle_primary_refresh_coordinator",
    object_id: "vehicle_primary_refresh_coordinator",
    state_topic: "homeassistant/vehicle_primary/refresh/state",
    value_template: "{{ value_json.state }}",
    json_attributes_topic: "homeassistant/vehicle_primary/refresh/state",
    icon: "mdi:car-clock",
    device: {
        identifiers: ["vehicle_primary_bluelink"],
        name: "vehicle_primary",
        manufacturer: "Hyundai"
    }
};

return [[
    {
        topic: "homeassistant/sensor/creta_refresh_coordinator/config",
        payload: "",
        retain: true,
        qos: 1
    },
    {
        topic: "homeassistant/sensor/vehicle_primary_refresh_coordinator_source/config",
        payload: "",
        retain: true,
        qos: 1
    },
    {
        topic: "homeassistant/sensor/vehicle_primary_refresh_coordinator/config",
        payload: JSON.stringify(discovery),
        retain: true,
        qos: 1
    },
    {
        topic: "homeassistant/vehicle_primary/refresh/state",
        payload: JSON.stringify(status),
        retain: true,
        qos: 1
    }
]];

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

if (TEST_MODE) {
    msg.payload = {
        ...msg.payload,
        side_effect: "vehicle_primary.force_refresh",
        simulated: true,
        dispatched: false,
        dry_run_at: Number(msg.payload?.test_now) || Date.now()
    };
    node.status({
        fill: "blue",
        shape: "dot",
        text: "TESTE: force_refresh bloqueado no dry-run"
    });
    return [null, msg];
}

return [msg, null];

/* O retorno do serviço prova apenas aceitação da chamada pelo Home Assistant.
 * Sucesso depende de timestamps novos nas entidades e é confirmado pelo
 * normalizador após a rechecagem. */
const key = "security_vehicle_primary_refresh_v1";
const AWAY_INTERVAL_MS = 15 * 60 * 1000;
const HOME_INTERVAL_MS = 30 * 60 * 1000;
const state = flow.get(key, "persistent") ?? {};
const now = Date.now();
const intervalMs = [AWAY_INTERVAL_MS, HOME_INTERVAL_MS]
    .includes(Number(state.interval_ms))
        ? Number(state.interval_ms)
        : AWAY_INTERVAL_MS;
state.request_in_flight = false;
state.in_flight_until = null;
state.service_accepted_at = now;
state.next_allowed_at = Math.max(
    Number(state.next_allowed_at ?? 0),
    now + intervalMs
);
state.state = "awaiting_evidence";
state.reason = state.recovery_reason ?? "service_accepted_awaiting_evidence";
state.next_retry_at = Number(state.next_allowed_at ?? 0) || null;
state.cooldown_until = null;
state.updated_at = now;
flow.set(key, state, "persistent");
node.status({
    fill: "yellow",
    shape: "ring",
    text: "serviço aceito; aguardando evidência nova"
});
return msg;

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

if (TEST_MODE) {
    msg.payload = {
        ...msg.payload,
        side_effect: "vehicle_primary.refresh_trip_info",
        simulated: true,
        dispatched: false,
        dry_run_at: Number(msg.payload?.test_now) || Date.now()
    };
    return [null, msg];
}

return [msg, null];

msg.payload = {
    ...msg.payload,
    test_mode: true,
    simulated: true,
    dispatched: false,
    external_call_sent: false,
    terminal: "vehicle_primary_full_dry_run"
};
flow.set("vehicle_primary_last_dry_run_v1", msg.payload);
node.status({
    fill: "blue",
    shape: "dot",
    text:
        "TESTE dry-run: " +
        String(msg.payload.side_effect ?? "nenhuma ação") +
        " dispatched=false"
});
return null;

const kind = msg.payload?.kind;
const FUTURE_TOLERANCE_MS = 60 * 1000;

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const TEST_CASE =
    msg._location_test_case ??
    msg.payload?.test_case ??
    null;

function contextKey(base) {
    return TEST_MODE ? `${base}__test` : base;
}

function ctxGet(base, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.get(key)
        : flow.get(key, store);
}

function ctxSet(base, value, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.set(key, value)
        : flow.set(key, value, store);
}

function nextRefreshCycle() {
    const key = "refresh_cycle_clock";
    const previous = Number(ctxGet(key) ?? 0);
    const cycle = Math.max(
        Date.now(),
        Number.isFinite(previous) ? previous + 1 : 0
    );
    ctxSet(key, cycle);
    return cycle;
}

function markTest(message) {
    if (!message || !TEST_MODE) return message;

    message._location_test = true;
    message._location_test_case = TEST_CASE;

    if (message.payload && typeof message.payload === "object") {
        message.payload.test_mode = true;
        message.payload.test_case = TEST_CASE;
    }

    return message;
}

function newPending(cycle, options = {}) {
    return {
        cycle,
        people_received: false,
        vehicle_primary_received: false,
        people_ready: false,
        vehicle_primary_ready: false,
        emitted: false,
        started_at: cycle,
        force_recovery: options.force_recovery === true,
        require_lighting_ready: options.require_lighting_ready === true,
        request_reason: options.request_reason ?? null
    };
}

/* Reset de TESTE: usa somente caches __test. */
if (kind === "test_reset" && TEST_MODE) {
    ctxSet("refresh_pending", undefined);
    ctxSet("people_context_v1", undefined);
    ctxSet("vehicle_primary_context_v1", undefined);

    const cycle = nextRefreshCycle();
    msg._location_test_reset = true;
    msg.payload = {
        contract: "security.snapshot-request.v1",
        kind: "snapshot_request",
        refresh_cycle_id: cycle,
        origin: "contexto_chegadas",
        reason: "manual_location_test_reset",
        requested_at: cycle
    };
    markTest(msg);

    node.status({
        fill: "blue",
        shape: "dot",
        text: "teste compartilhado resetado"
    });

    return [msg, null, null];
}

/*
 * Um refresh_tick sempre inicia um snapshot dos dois domínios.
 * A decisão de forçar refresh físico será feita DEPOIS que ambos
 * responderem, mesmo se um deles ainda estiver pending/stale.
 */
if (kind === "refresh_tick") {
    const requestedReason =
        msg.payload?.reason ?? "startup_or_periodic_reconciliation";
    const forceRecovery =
        msg.payload?.force_recovery === true;
    const requireLightingReady =
        msg.payload?.require_lighting_ready === true;

    /*
     * Evita que o tick periódico de 30 s sobrescreva um ciclo de recovery
     * que ainda está esperando os snapshots. Se já existe um ciclo em voo,
     * uma solicitação mais forte apenas promove esse ciclo para recovery.
     */
    const currentPending =
        ctxGet("refresh_pending");

    const currentInFlight =
        currentPending &&
        currentPending.emitted !== true &&
        Number.isFinite(
            Number(currentPending.started_at)
        ) &&
        Date.now() -
            Number(currentPending.started_at) <
            10 * 1000;

    if (currentInFlight) {
        if (forceRecovery) {
            currentPending.force_recovery = true;
            currentPending.require_lighting_ready =
                currentPending.require_lighting_ready === true ||
                requireLightingReady;
            currentPending.request_reason =
                requestedReason;

            ctxSet(
                "refresh_pending",
                currentPending
            );

            node.status({
                fill: "yellow",
                shape: "ring",
                text: "ciclo em voo promovido para recovery"
            });
        }

        return null;
    }

    const cycle = nextRefreshCycle();

    ctxSet(
        "refresh_pending",
        newPending(cycle, {
            force_recovery: forceRecovery,
            require_lighting_ready: requireLightingReady,
            request_reason: requestedReason
        })
    );

    msg.payload = {
        contract: "security.snapshot-request.v1",
        kind: "snapshot_request",
        refresh_cycle_id: cycle,
        origin: "contexto_chegadas",
        reason: TEST_MODE
            ? "manual_location_test"
            : requestedReason,
        force_recovery: forceRecovery,
        require_lighting_ready: requireLightingReady,
        requested_at: cycle
    };

    markTest(msg);
    return [msg, null, null];
}

if (kind === "people_context" || kind === "vehicle_primary_context") {
    const domain = kind === "people_context" ? "people" : "vehicle_primary";
    const key = domain + "_context_v1";
    const previous = ctxGet(key);

    const incomingAt = Number(
        msg.payload.updated_at ??
        msg.payload.context?.updated_at ??
        0
    );
    const previousAt = Number(previous?.updated_at ?? 0);

    let cached = previous;
    let accepted = false;
    let rejectedReason = null;

    if (incomingAt > Date.now() + FUTURE_TOLERANCE_MS) {
        rejectedReason = "future_timestamp";
        node.warn(
            "contexto_chegadas: snapshot " + domain +
            (TEST_MODE ? " [TESTE]" : "") +
            " no futuro; cache atual preservado"
        );
    } else if (
        previous &&
        incomingAt &&
        previousAt &&
        incomingAt < previousAt
    ) {
        rejectedReason = "out_of_order";
        node.warn(
            "contexto_chegadas: snapshot " + domain +
            (TEST_MODE ? " [TESTE]" : "") +
            " fora de ordem; cache atual preservado"
        );
    } else if (
        !previous ||
        (incomingAt && (!previousAt || incomingAt > previousAt))
    ) {
        ctxSet(key, msg.payload.context);
        cached = msg.payload.context;
        accepted = true;
    } else if (!incomingAt) {
        rejectedReason = "missing_timestamp";
        node.warn(
            "contexto_chegadas: snapshot " + domain +
            " sem timestamp; cache atual preservado"
        );
    } else if (
        incomingAt === previousAt &&
        JSON.stringify(previous) !== JSON.stringify(msg.payload.context)
    ) {
        /* Mesmo timestamp da fonte; aceita mudança de estado derivado. */
        ctxSet(key, msg.payload.context);
        cached = msg.payload.context;
        accepted = true;
        node.status({
            fill: "yellow",
            shape: "dot",
            text: "contexto " + domain + " atualizado no mesmo timestamp"
        });
    }

    let refresh = null;
    const pending = ctxGet("refresh_pending");

    if (
        pending &&
        msg.payload.refresh_cycle_id === pending.cycle
    ) {
        /*
         * IMPORTANTE: "recebeu snapshot" e "snapshot ready" são coisas
         * diferentes. O v7 usava ready como confirmação de recebimento,
         * impedindo justamente o refresh que recuperaria um domínio stale.
         */
        pending[domain + "_received"] = true;
        pending[domain + "_ready"] = accepted
            ? msg.payload.ready === true
            : cached?.ready === true;

        if (
            pending.people_received &&
            pending.vehicle_primary_received &&
            !pending.emitted
        ) {
            pending.emitted = true;

            const people = ctxGet("people_context_v1") ?? {};
            const vehicle_primary = ctxGet("vehicle_primary_context_v1") ?? {};
            const contextsReady =
                pending.people_ready === true &&
                pending.vehicle_primary_ready === true;

            const recoveryNeeded =
                !contextsReady ||
                pending.force_recovery === true;

            const recoveryReason =
                pending.request_reason ??
                (contextsReady
                    ? "paired_ready_snapshots"
                    : "readiness_recovery_needed");

            refresh = {
                payload: {
                    contract: "security.refresh-command.v1",
                    kind: "refresh_command",
                    refresh_cycle_id: pending.cycle,
                    anyone_away:
                        people?.anyone_away === true ||
                        vehicle_primary?.away === true,
                    resident_primary_state:
                        people?.resident_primary?.state ?? null,
                    resident_secondary_state:
                        people?.resident_secondary?.state ?? null,
                    people_ready: pending.people_ready === true,
                    vehicle_primary_ready: pending.vehicle_primary_ready === true,
                    contexts_ready: contextsReady,
                    recovery_needed: recoveryNeeded,
                    force_recovery: pending.force_recovery === true,
                    require_lighting_ready:
                        pending.require_lighting_ready === true,
                    recovery_reason: recoveryReason,
                    origin: "contexto_chegadas",
                    reason: TEST_MODE
                        ? (recoveryNeeded
                            ? "test_readiness_recovery_needed"
                            : "paired_ready_test_snapshots")
                        : (recoveryNeeded
                            ? recoveryReason
                            : "paired_ready_snapshots"),
                    issued_at: Date.now(),
                    ready: contextsReady,
                    rejected_snapshot_reason: rejectedReason
                }
            };

            markTest(refresh);

            node.status({
                fill: recoveryNeeded ? "yellow" : "green",
                shape: "dot",
                text: recoveryNeeded
                    ? "refresh de recuperação emitido"
                    : "snapshots ready; política de refresh emitida"
            });
        }

        ctxSet("refresh_pending", pending);
    }

    return refresh ? [null, refresh] : null;
}

return null;

if (msg.payload?.event_type === "test") return null;

const requestedAt = Date.now();
node.log?.("VEHICLE_PRIMARY_REFRESH_REQUESTED origin=dashboard reason=manual_force");

return {
    payload: {
        kind: "refresh_tick",
        origin: "vehicle_primary_dashboard",
        reason: "manual_force",
        force_recovery: true,
        require_lighting_ready: false,
        requested_at: requestedAt
    }
};

const kind = msg.payload?.kind;

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const TEST_CASE =
    msg._location_test_case ??
    msg.payload?.test_case ??
    null;

const incomingAt = Number(
    msg.payload?.updated_at ??
    msg.payload?.context?.updated_at ??
    0
);

const FUTURE_TOLERANCE_MS = 60 * 1000;
const PENDING_ARRIVAL_TTL_MS = 2 * 60 * 1000;

function contextKey(base) {
    return TEST_MODE ? `${base}__test` : base;
}

function updateCache(baseKey) {
    const key = contextKey(baseKey);
    const old = flow.get(key);
    const oldAt = Number(old?.updated_at ?? 0);

    if (
        incomingAt > Date.now() + FUTURE_TOLERANCE_MS ||
        (
            old &&
            incomingAt &&
            oldAt &&
            incomingAt < oldAt
        )
    ) {
        node.warn(
            "iluminacao_seguranca: snapshot" +
            (TEST_MODE ? " [TESTE]" : "") +
            " fora de ordem ou no futuro; descartado"
        );
        return false;
    }

    if (
        !old ||
        (
            incomingAt &&
            (!oldAt || incomingAt > oldAt)
        )
    ) {
        flow.set(key, msg.payload.context);
        return true;
    }

    if (!incomingAt) {
        node.warn(
            "iluminacao_seguranca: snapshot sem timestamp; cache atual preservado"
        );
        return false;
    }

    if (
        incomingAt === oldAt &&
        JSON.stringify(old) !==
            JSON.stringify(msg.payload.context)
    ) {
        /*
         * Mesmo timestamp de origem, mas estado derivado diferente.
         * A versão recebida por último é a interpretação mais recente.
         */
        flow.set(key, msg.payload.context);

        node.status({
            fill: "yellow",
            shape: "dot",
            text: "contexto atualizado no mesmo timestamp"
        });

        return true;
    }

    return false;
}

let contextAccepted = true;

if (kind === "people_context") {
    contextAccepted =
        updateCache("people_context_v1");
}

if (kind === "vehicle_primary_context") {
    contextAccepted =
        updateCache("vehicle_primary_context_v1");
}

if (kind === "sun_context") {
    flow.set(
        "sun_below_horizon",
        msg.payload.sun_below_horizon === true
    );
}

/*
 * RESET de cenário sintético também elimina qualquer chegada pendente
 * daquele cenário. A fila de produção usa outra chave e não é tocada.
 */
if (
    TEST_MODE &&
    msg._location_test_reset === true
) {
    for (const base of [
        "security_light_pending_arrival_v1",
        "security_light_lifecycle_v1",
        "security_light_last_dry_run_v1",
        "security_light_turn_on_notification_latch_v1"
    ]) {
        flow.set(contextKey(base), null);
    }
}

/*
 * Contexto sintético não dispara reconciliação física.
 */
const reconcile =
    TEST_MODE
        ? null
        : {
            payload: {
                kind: "reconcile_signal",
                reason: "context_update"
            }
        };

const vehicle_primary =
    flow.get(
        contextKey("vehicle_primary_context_v1")
    ) ?? {};

const lifecycle =
    flow.get(
        "security_light_lifecycle_v1",
        "persistent"
    ) ?? {};

const original = msg.payload;

/*
 * Reprocessa uma chegada curta que chegou enquanto o contexto do
 * vehicle_primary/motor ainda estava em recovery. O reprocessamento acontece
 * somente quando já existem dados suficientes para decidir e dentro
 * de uma janela curta, evitando acender por uma chegada antiga.
 */
const pendingKey =
    contextKey(
        "security_light_pending_arrival_v1"
    );

let pending =
    flow.get(pendingKey);

let replay = null;

if (pending) {
    const queuedAt =
        Number(pending.queued_at ?? 0);

    const expiresAt =
        Number(pending.expires_at ?? 0);

    const validPending =
        pending.version === 1 &&
        pending.message &&
        Number.isFinite(queuedAt) &&
        Number.isFinite(expiresAt) &&
        queuedAt <= Date.now() + FUTURE_TOLERANCE_MS &&
        Date.now() <= expiresAt &&
        expiresAt - queuedAt <=
            PENDING_ARRIVAL_TTL_MS + 1000;

    if (!validPending) {
        flow.set(pendingKey, null);

        node.warn(
            "iluminacao_seguranca: chegada pendente expirou " +
            "antes da recuperação do contexto"
        );

        pending = null;
    }
}

const vehicle_primaryLightingReady =
    vehicle_primary.ready === true &&
    (
        vehicle_primary.lighting_ready === true ||
        (
            vehicle_primary.engine_state_valid === true &&
            vehicle_primary.engine_stale !== true
        )
    );

const vehicle_primaryReadyForArrival =
    vehicle_primaryLightingReady &&
    vehicle_primary.in_use === true &&
    vehicle_primary.engine_on === true &&
    vehicle_primary.engine_state_valid === true &&
    vehicle_primary.engine_stale !== true;

const replayReady =
    pending &&
    vehicle_primaryReadyForArrival &&
    flow.get("sun_ready") === true;

if (replayReady) {
    replay = {
        ...pending.message,
        payload: {
            ...(pending.message.payload ?? {}),
            arrival_replayed_after_context_recovery: true,
            arrival_originally_queued_at:
                pending.queued_at,
            arrival_replayed_at:
                Date.now()
        }
    };

    replay._arrival_replay = true;

    if (TEST_MODE) {
        replay._location_test = true;
        replay._location_test_case =
            TEST_CASE ??
            pending.message._location_test_case ??
            null;

        replay.payload.test_mode = true;
        replay.payload.test_case =
            replay._location_test_case;
    }

    flow.set(pendingKey, null);

    node.status({
        fill: "green",
        shape: "dot",
        text: "chegada pendente reprocessada após recovery"
    });
}

/*
 * Saída 1 mantém o processamento normal de contexto/lifecycle.
 * Se o snapshot de Pessoas/vehicle_primary foi rejeitado, não propaga esse
 * contexto para regras de desligamento, mas ainda permite replay
 * baseado no cache válido já existente.
 */
let lifecycleMsg = msg;

if (
    (
        kind === "people_context" ||
        kind === "vehicle_primary_context"
    ) &&
    !contextAccepted
) {
    lifecycleMsg = null;
}

if (lifecycleMsg) {
    lifecycleMsg.payload = {
        event:
            original?.event ??
            "context_update",
        reason:
            original?.reason,
        source:
            original?.source,
        trigger_state:
            original?.trigger_state,
        trigger_prev_state:
            original?.trigger_prev_state,
        confirmed_home_transition:
            original?.confirmed_home_transition === true,
        vehicle_primary_ready:
            vehicle_primary.ready === true,
        vehicle_primary_lighting_ready:
            vehicle_primaryLightingReady,
        vehicle_primary_engine_on:
            vehicle_primary.engine_on,
        vehicle_primary_engine_state_valid:
            vehicle_primary.engine_state_valid === true,
        vehicle_primary_unlocked:
            vehicle_primary.unlocked,
        vehicle_primary_in_use:
            vehicle_primary.in_use,
        active:
            lifecycle.active_by_arrival === true
    };

    if (TEST_MODE) {
        lifecycleMsg._location_test = true;
        lifecycleMsg._location_test_case =
            TEST_CASE;

        lifecycleMsg.payload.test_mode = true;
        lifecycleMsg.payload.test_case =
            TEST_CASE;
    }
}

/*
 * OUTPUT 1 = contexto para lifecycle/desligamento
 * OUTPUT 2 = sinal de reconciliação física
 * OUTPUT 3 = arrival reprocessado após recovery
 */
return [
    lifecycleMsg,
    reconcile,
    replay
];

if (msg.payload?.kind !== "arrival") {
    return null;
}

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const TEST_CASE =
    msg._location_test_case ??
    msg.payload?.test_case ??
    null;

const PENDING_ARRIVAL_TTL_MS =
    2 * 60 * 1000;

const RECOVERY_REQUEST_THROTTLE_MS =
