const logicReady =
    vehicle_primaryLightingReady &&
    sunReady;

const diagnostic = {
    ...msg,
    payload: {
        ...(msg.payload ?? {}),
        diagnostic:
            "arrival_trigger_received",
        gps_trigger_functional: true,
        decision_context_ready:
            logicReady,
        people_context_ready:
            people.ready === true,
        vehicle_primary_context_ready:
            vehicle_primary.ready === true,
        vehicle_primary_lighting_ready:
            vehicle_primaryLightingReady,
        vehicle_primary_engine_state_valid:
            vehicle_primary.engine_state_valid === true,
        vehicle_primary_engine_stale:
            vehicle_primary.engine_stale === true,
        sun_ready:
            sunReady,
        sun_below_horizon:
            flow.get(
                "sun_below_horizon"
            ) === true,
        vehicle_primary_in_use:
            vehicle_primary.in_use,
        vehicle_primary_engine_on:
            vehicle_primary.engine_on,
        reflector_state:
            physical,
        reflector_physical_fresh:
            physicalFresh,
        reflector_reconciled:
            lightReconciled,
        would_evaluate_turn_on:
            logicReady,
        arrival_replay:
            msg._arrival_replay === true
    }
};

if (TEST_MODE) {
    diagnostic._location_test = true;
    diagnostic._location_test_case =
        TEST_CASE;
    diagnostic.payload.test_mode = true;
    diagnostic.payload.test_case =
        TEST_CASE;
}

node.status({
    fill: logicReady
        ? "green"
        : "yellow",
    shape: "dot",
    text:
        `${TEST_MODE ? "TESTE " : ""}` +
        `GPS ${msg.payload.source}/${msg.payload.arrival_stage} | ` +
        (
            logicReady
                ? "motor/contextos OK"
                : (
                    !vehicle_primaryLightingReady
                        ? "vehicle_primary/motor pendente"
                        : "luminosidade pendente"
                )
        ) +
        ` | ${
            flow.get(
                "sun_below_horizon"
            ) === true
                ? "escuro"
                : "claro"
        }`
});

let recoveryRequest = null;

if (!logicReady) {
    /*
     * Não perde a chegada. Guarda por no máximo 2 minutos para que
     * Atualizar contexto de alto nível a reenvie a este nó quando o
     * recovery do vehicle_primary/motor terminar.
     */
    const pendingKey =
        contextKey(
            "security_light_pending_arrival_v1"
        );

    const now =
        Date.now();

    const originalQueuedAt =
        Number(
            msg.payload
                ?.arrival_originally_queued_at ??
            now
        );

    const queuedAt =
        Number.isFinite(originalQueuedAt) &&
        originalQueuedAt > 0
            ? originalQueuedAt
            : now;

    const expiresAt =
        queuedAt +
        PENDING_ARRIVAL_TTL_MS;

    const eventAt =
        Number(
            msg.payload?.event_at ??
            msg.payload?.updated_at ??
            now
        );

    const existing =
        flow.get(pendingKey);

    const existingEventAt =
        Number(
            existing?.event_at ?? 0
        );

    /*
     * Mantém o evento mais recente, mas um replay não estende a TTL.
     */
    if (
        !existing ||
        !Number.isFinite(existingEventAt) ||
        eventAt >= existingEventAt
    ) {
        flow.set(
            pendingKey,
            {
                version: 1,
                queued_at:
                    queuedAt,
                expires_at:
                    expiresAt,
                event_at:
                    eventAt,
                message: {
                    ...msg,
                    payload: {
                        ...(msg.payload ?? {})
                    }
                }
            }
        );
    }

    diagnostic.payload
        .pending_arrival_queued = true;

    diagnostic.payload
        .pending_arrival_expires_at =
            expiresAt;

    /*
     * Se o que falta é o vehicle_primary/motor, força recovery imediatamente.
     * Se só falta luminosidade, o próprio sun_context fará o replay.
     */
    if (!vehicle_primaryLightingReady) {
        const recoveryKey =
            contextKey(
                "security_light_last_recovery_request_at"
            );

        const lastRecoveryAt =
            Number(
                flow.get(recoveryKey) ?? 0
            );

        const canRequest =
            !Number.isFinite(lastRecoveryAt) ||
            lastRecoveryAt <= 0 ||
            now - lastRecoveryAt >=
                RECOVERY_REQUEST_THROTTLE_MS;

        if (canRequest) {
            flow.set(
                recoveryKey,
                now
            );

            const recoveryReason =
                vehicle_primary.ready === true
                    ? "arrival_engine_recovery_needed"
                    : "arrival_vehicle_primary_context_recovery_needed";

            recoveryRequest = {
                _location_test:
                    TEST_MODE,
                _location_test_case:
                    TEST_CASE,
                payload: {
                    kind:
                        "refresh_tick",
                    origin:
                        "iluminacao_seguranca",
                    reason:
                        recoveryReason,
                    force_recovery:
                        true,
                    require_lighting_ready:
                        true,
                    requested_at:
                        now,
                    arrival_source:
                        msg.payload.source,
                    arrival_stage:
                        msg.payload.arrival_stage,
                    test_mode:
                        TEST_MODE,
                    test_case:
                        TEST_CASE
                }
            };

            diagnostic.payload
                .context_recovery_requested =
                    true;

            diagnostic.payload
                .context_recovery_reason =
                    recoveryReason;
        } else {
            diagnostic.payload
                .context_recovery_requested =
                    false;

            diagnostic.payload
                .context_recovery_throttled =
                    true;
        }
    }

    node.warn(
        "iluminacao_seguranca: trigger de chegada recebido; " +
        (
            !vehicle_primaryLightingReady
                ? "vehicle_primary/motor ainda não ready — chegada preservada para replay"
                : "luminosidade ainda não ready — chegada preservada para replay"
        )
    );

    /*
     * OUTPUT 1 = decisão normal
     * OUTPUT 2 = diagnóstico GPS
     * OUTPUT 3 = recovery imediato de contexto
     */
    return [
        null,
        diagnostic,
        recoveryRequest
    ];
}

/*
 * Se chegamos aqui, o evento atual já pode ser decidido.
 * Remove uma fila anterior para impedir replay duplicado.
 */
flow.set(
    contextKey(
        "security_light_pending_arrival_v1"
    ),
    null
);

const eventAt =
    Number(
        msg.payload.event_at ??
        msg.payload.updated_at ??
        Date.now()
    );

msg.payload.arrival_key = [
    msg.payload.source,
    msg.payload.arrival_stage,
    eventAt
].join(":");

msg.payload.sun_below_horizon =
    flow.get(
        "sun_below_horizon"
    ) === true;

msg.payload.vehicle_primary_in_use =
    vehicle_primary.in_use;

msg.payload.vehicle_primary_engine_on =
    vehicle_primary.engine_on;

msg.payload.vehicle_primary_engine_state_valid =
    vehicle_primary.engine_state_valid === true;

msg.payload.vehicle_primary_lighting_ready =
    vehicle_primaryLightingReady;

msg.payload.active =
    lifecycle.active_by_arrival === true ||
    physical === "on";

msg.payload.reflector_state =
    physical;

msg.payload.reflector_physical_fresh =
    physicalFresh;

msg.payload.reflector_reconciled =
    lightReconciled;

if (TEST_MODE) {
    msg._location_test = true;
    msg._location_test_case =
        TEST_CASE;
    msg.payload.test_mode = true;
    msg.payload.test_case =
        TEST_CASE;
}

/*
 * OUTPUT 1 = continua avaliando acendimento.
 * OUTPUT 2 = diagnóstico do trigger GPS/chegada.
 * OUTPUT 3 = recovery imediato quando contexto insuficiente.
 */
return [
    msg,
    diagnostic,
    null
];

/*
 * Regra física v11:
 * o refletor só pode ser ligado quando o vehicle_primary está efetivamente em uso
 * E o motor atual foi observado ligado/running.
 *
 * Uma chegada pode preceder a atualização do motor na integração. Nesse caso,
 * preserva o evento por até 2 minutos para replay quando surgir ON atual.
 *
 * Em test_mode o nó apresenta o resultado e continua pelo mesmo caminho
 * lógico. A separação real/simulado ocorre somente na fronteira de despacho.
 */
const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const PENDING_ARRIVAL_TTL_MS =
    2 * 60 * 1000;

function contextKey(base) {
    return TEST_MODE
        ? base + "__test"
        : base;
}

function preserveArrivalForEngineOn() {
    if (msg.payload?.kind !== "arrival") {
        return false;
    }

    const now = Date.now();
    const pendingKey = contextKey(
        "security_light_pending_arrival_v1"
    );

    const originalQueuedAt = Number(
        msg.payload?.arrival_originally_queued_at ?? now
    );

    const queuedAt =
        Number.isFinite(originalQueuedAt) &&
        originalQueuedAt > 0 &&
        originalQueuedAt <= now + 60 * 1000
            ? originalQueuedAt
            : now;

    const eventAt = Number(
        msg.payload?.event_at ??
        msg.payload?.updated_at ??
        now
    );

    const existing = flow.get(pendingKey);
    const existingEventAt = Number(
        existing?.event_at ?? 0
    );

    if (
        existing &&
        Number.isFinite(existingEventAt) &&
        existingEventAt > eventAt
    ) {
        return true;
    }

    flow.set(pendingKey, {
        version: 1,
        queued_at: queuedAt,
        expires_at:
            queuedAt + PENDING_ARRIVAL_TTL_MS,
        event_at: eventAt,
        wait_reason:
            "vehicle_engine_on_after_arrival",
        message: {
            ...msg,
            payload: {
                ...(msg.payload ?? {})
            }
        }
    });

    return true;
}

if (
    msg.payload?.vehicle_primary_in_use !== true ||
    msg.payload?.vehicle_primary_engine_on !== true ||
    msg.payload?.vehicle_primary_engine_state_valid !== true
) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: preserveArrivalForEngineOn()
            ? (
                TEST_MODE
                    ? "TESTE: aguardando motor ON — chegada preservada"
                    : "aguardando motor ON — chegada preservada"
            )
            : (
                TEST_MODE
                    ? "TESTE: bloqueado — motor OFF"
                    : "vehicle_primary sem motor ON atual"
            )
    });
    return null;
}

if (TEST_MODE) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "TESTE: gate aprovado — continuando dry-run"
    });
    msg.payload.simulated = true;
    msg.payload.dispatched = false;
} else {
    const lifecycle =
        flow.get(
            "security_light_lifecycle_v1",
            "persistent"
        ) ?? {};

    const until =
        Number(
            lifecycle.cooldown_until ?? 0
        );

    if (
        Number.isFinite(until) &&
        Date.now() < until
    ) {
        node.status({
            fill: "grey",
            shape: "ring",
            text: "iluminação em cooldown"
        });
        return null;
    }
}

msg.payload.vehicle_primary_gate =
    "fresh_engine_on";

return msg;

const now = Date.now();
const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;
const NOTIFICATION_LATCH_KEY =
    "security_light_turn_on_notification_latch_v1";

function contextKey(base) {
    return TEST_MODE ? base + "__test" : base;
}

function ctxGet(base, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.get(key)
        : flow.get(key, store);
}

function ctxSet(base, value, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.set(key, value)
        : flow.set(key, value, store);
}

const physical =
    flow.get("security_light_physical_state") ?? "unknown";

const physicalObservedAt = Number(
    flow.get("security_light_physical_observed_at") ?? 0
);

