    !allowedStages.has(stage) ||
    !Array.isArray(arriving) ||
    !arriving.includes(source)
) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "evento de chegada ignorado"
    });
    return [null, null];
}

msg.arrival_source = source;
msg.arrival_stage = stage;
msg.arrival_detected_at = Date.now();

if (TEST_MODE) {
    msg._location_test = true;
    msg._location_test_case = TEST_CASE;
    msg.alarm_arrival_test = true;

