        fill: "blue",
        shape: "dot",
        text: `TESTE recebido ${source}: ${stage}`
    });

    // Saída 2: trilha de teste, nunca desarma o alarme.
    return [null, msg];
}

node.status({
    fill: "blue",
    shape: "dot",
    text: `${source}: ${stage}`
});

// Saída 1: chegada real.
return [msg, null];

const COOLDOWN_MS = 60 * 1000;
const CONFIRMATION_TTL_MS = 5 * 60 * 1000;
