    msg.payload?.event?.action ??
    msg.payload?.action ??
    msg.event?.action ??
    null;

if (
    typeof action !== "string" ||
    action.length === 0
) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "evento sem action"
    });

    return [null, null];
}

const now = Date.now();

/*
 * Uma action de TESTE só é válida se a pendência tiver sido criada
 * depois do reset mais recente, seja ele vindo dos testes de localização
 * ou do botão RESETAR teste do alarme desta própria aba.
