const sharedTestState =
    global.get("security_location_test_state_v1") ?? {};

const locationResetAt =
    Number(sharedTestState.reset_at ?? 0);

const alarmResetAt =
    Number(global.get("alarm_arrival_test_reset_at") ?? 0);

const latestTestResetAt = Math.max(
    Number.isFinite(locationResetAt) && locationResetAt > 0
        ? locationResetAt
        : 0,
    Number.isFinite(alarmResetAt) && alarmResetAt > 0
        ? alarmResetAt
        : 0
);

if (testPending) {
    const createdAt = Number(testPending.createdAt ?? 0);

    if (
        latestTestResetAt > 0 &&
        (
