msg._location_test_case = testCase;
msg.alarm_arrival_test = true;

msg.confirm_action = confirmAction;
msg.cancel_action = cancelAction;
msg.confirm_action_title = "Confirmar teste";
msg.cancel_action_title = "Cancelar teste";
msg.notification_title = "[TESTE] Confirmação do alarme";
msg.notification_tag = "alarm_arrival_confirmation_test";

