}

msg.payload = {
    event: {
        action: msg.confirm_action
    },
    test_mode: true,
    simulated: true,
    dispatched: false
};

msg.alarm_arrival_test_notification = {
    simulated: true,
    dispatched: false
};

node.status({
    fill: "yellow",
    shape: "dot",
    text: "TESTE: confirmação mobile simulada"
});

return msg;

if (
    msg._location_test !== true ||
    msg.alarm_arrival_test !== true
) {
