const TEST_MODE = msg._vpn_test === true || msg.payload?.test_mode === true;
const KEY = TEST_MODE ? "vpn_monitor_internet_v1__test" : "vpn_monitor_internet_v1";
const STORE = TEST_MODE ? undefined : "persistent";
let value = msg.payload;
if (Buffer.isBuffer(value)) value = value.toString("utf8");
if (value && typeof value === "object") value = value.state ?? value.phase;
const phase = String(value ?? "unknown").toLowerCase();
if (!new Set(["online", "offline", "checking", "recovering"]).has(phase)) return null;
const state = { phase, updated_at: Number(msg.vpn_now ?? Date.now()) };
if (STORE) flow.set(KEY, state, STORE);
else flow.set(KEY, state);
msg.payload = { test_mode: TEST_MODE, observer_kind: "internet_state", phase };
return msg;

const TEST_MODE = msg._vpn_test === true || msg.payload?.test_mode === true;
const suffix = TEST_MODE ? "__test" : "";
const STORE = TEST_MODE ? undefined : "persistent";
const now = Number(msg.vpn_now ?? Date.now());
const get = (key) => STORE ? flow.get(`${key}${suffix}`, STORE) : flow.get(`${key}${suffix}`);
const set = (key, value) => STORE ? flow.set(`${key}${suffix}`, value, STORE) : flow.set(`${key}${suffix}`, value);
const EXPECTED = [{ role: "vpn_primary", kind: "tailscale", label: "Tailscale" }];
const FAILURE_CONFIRM_MS = 2 * 60 * 1000;
const RECOVERY_CONFIRM_MS = 60 * 1000;
const REPORT_STALE_MS = 3 * 60 * 1000;
const REMINDER_MS = 24 * 60 * 60 * 1000;

const report = get("vpn_monitor_report_v1") ?? { checked_at: null, received_at: 0, vpns: [] };
const internet = get("vpn_monitor_internet_v1") ?? { phase: "unknown" };
const states = get("vpn_monitor_state_v1") ?? {};
const reportCheckedAt = Date.parse(report.checked_at ?? "");
const reportFresh = Number.isFinite(reportCheckedAt) && now - reportCheckedAt <= REPORT_STALE_MS;
const samples = new Map((report.vpns ?? []).map((vpn) => [vpn.role, vpn]));
const internetOnline = internet.phase === "online";
const down = [];
const recovery = [];
const publications = [];

const reasonText = {
    authentication_required: "a VPN requer nova autenticação",
    backend_stopped: "o serviço da VPN está parado",
    backend_unavailable: "o backend da VPN não está operacional",
    status_command_failed: "a consulta local de estado falhou",
    status_timeout: "a consulta local de estado excedeu o tempo limite",
    invalid_status: "o serviço retornou estado inválido",
    vpn_not_detected: "a VPN instalada não foi detectada pelo publicador",
    telemetry_stale: "o monitor do host deixou de atualizar o estado",
    not_online: "a VPN não está conectada"
};

for (const expected of EXPECTED) {
    const previous = states[expected.role] ?? {
        phase: "checking",
        incident_open: false,
        failure_started_at: null,
        recovery_started_at: null,
        last_notification_at: null
    };
    const sample = samples.get(expected.role);
    const healthy = reportFresh && sample?.healthy === true;
    const failureReason = !reportFresh
        ? "telemetry_stale"
        : sample
            ? String(sample.reason ?? "not_online")
            : "vpn_not_detected";
    const current = { ...previous, kind: expected.kind, label: expected.label };

    if (!internetOnline) {
        current.phase = "suppressed_internet";
        current.failure_started_at = null;
        current.recovery_started_at = null;
        current.reason = `internet_${internet.phase ?? "unknown"}`;
    } else if (!healthy) {
        current.recovery_started_at = null;
        current.reason = failureReason;
        if (!Number.isFinite(current.failure_started_at)) current.failure_started_at = now;
        const confirmed = now - current.failure_started_at >= FAILURE_CONFIRM_MS;
        current.phase = confirmed ? "offline" : "checking";
        const reminderDue =
            current.incident_open === true &&
            now - Number(current.last_notification_at ?? now) >= REMINDER_MS;
        if (confirmed && (current.incident_open !== true || reminderDue)) {
            current.incident_open = true;
            current.last_notification_at = now;
            current.last_outage_at = current.last_outage_at ?? new Date(current.failure_started_at).toISOString();
            down.push({
                _vpn_test: TEST_MODE,
                _vpn_side_effect: "notification",
                payload: { test_mode: TEST_MODE, observer_kind: "vpn_unavailable", vpn_role: expected.role },
                notification: {
                    id: `vpn_${expected.role}_failure`,
                    title: TEST_MODE ? `TESTE — VPN ${expected.label} indisponível` : `VPN ${expected.label} indisponível`,
                    message:
                        `A internet está disponível, mas a VPN ${expected.label} permanece ` +
                        `fora do ar há pelo menos 2 minutos: ${reasonText[failureReason] ?? reasonText.not_online}.`
                }
            });
        }
    } else {
        current.failure_started_at = null;
        current.reason = "running";
        if (current.incident_open === true) {
            if (!Number.isFinite(current.recovery_started_at)) current.recovery_started_at = now;
            if (now - current.recovery_started_at >= RECOVERY_CONFIRM_MS) {
                current.phase = "online";
                current.incident_open = false;
                current.last_recovery_at = new Date(now).toISOString();
                current.last_outage_at = null;
                current.last_notification_at = null;
                current.recovery_started_at = null;
                recovery.push({
                    _vpn_test: TEST_MODE,
                    _vpn_side_effect: "notification",
                    payload: { test_mode: TEST_MODE, observer_kind: "vpn_recovered", vpn_role: expected.role },
                    notification: {
                        id: `vpn_${expected.role}_recovered`,
                        dismiss_id: `vpn_${expected.role}_failure`,
                        title: TEST_MODE ? `TESTE — VPN ${expected.label} recuperada` : `VPN ${expected.label} recuperada`,
                        message: `A VPN ${expected.label} voltou a ficar online e permaneceu estável por 1 minuto.`
                    }
                });
            } else {
                current.phase = "recovering";
            }
        } else {
            current.phase = "online";
            current.recovery_started_at = null;
        }
    }

    current.last_checked_at = report.checked_at ?? null;
    states[expected.role] = current;
    const online = current.phase === "online" || current.phase === "recovering";
    const attributes = {
        state: current.phase,
        reason: current.reason,
        internet_state: internet.phase ?? "unknown",
        last_checked_at: current.last_checked_at,
        last_outage: current.last_outage_at ?? null,
        last_recovery: current.last_recovery_at ?? null
    };
    publications.push(
        { topic: `nodered/infrastructure/vpn/${expected.role}/connection`, payload: online ? "ON" : "OFF" },
        { topic: `nodered/infrastructure/vpn/${expected.role}/state`, payload: current.phase },
        { topic: `nodered/infrastructure/vpn/${expected.role}/attributes`, payload: JSON.stringify(attributes) }
    );
}

set("vpn_monitor_state_v1", states);
const phases = Object.values(states).map((state) => state.phase);
node.status({
    fill: phases.every((phase) => phase === "online") ? "green" : phases.some((phase) => phase === "offline") ? "red" : "yellow",
    shape: phases.every((phase) => phase === "online") ? "dot" : "ring",
    text: phases.join(", ") || "sem VPN configurada"
});

const wrapPublications = publications.map((publication) => ({
    _vpn_test: TEST_MODE,
    _vpn_side_effect: "mqtt",
    _vpn_payload_meta: { test_mode: TEST_MODE, observer_kind: "vpn_mqtt" },
    topic: publication.topic,
    payload: publication.payload
}));
return [down.length ? down : null, recovery.length ? recovery : null, wrapPublications.length ? wrapPublications : null];

const TEST_MODE = msg._vpn_test === true || msg.payload?.test_mode === true || msg._vpn_payload_meta?.test_mode === true;
if (!TEST_MODE) return [msg, null];
msg.payload = {
    test_mode: true,
    observer_kind: msg.payload?.observer_kind ?? msg._vpn_payload_meta?.observer_kind ?? "vpn_side_effect",
    side_effect: msg._vpn_side_effect ?? "unknown",
    simulated: true,
    dispatched: false
};
return [null, msg];

const TEST_MODE = msg._vpn_test === true || msg.payload?.test_mode === true || msg._vpn_payload_meta?.test_mode === true;
if (!TEST_MODE) return [msg, null];
msg.payload = {
    test_mode: true,
    observer_kind: msg.payload?.observer_kind ?? msg._vpn_payload_meta?.observer_kind ?? "vpn_side_effect",
    side_effect: msg._vpn_side_effect ?? "unknown",
    simulated: true,
    dispatched: false
};
return [null, msg];

const TEST_MODE = msg._vpn_test === true || msg.payload?.test_mode === true || msg._vpn_payload_meta?.test_mode === true;
if (!TEST_MODE) return [msg, null];
msg.payload = {
    test_mode: true,
    observer_kind: msg.payload?.observer_kind ?? msg._vpn_payload_meta?.observer_kind ?? "vpn_side_effect",
    side_effect: msg._vpn_side_effect ?? "unknown",
    simulated: true,
    dispatched: false
};
return [null, msg];

const availability = {
    availability_topic: "nodered/status",
    payload_available: "online",
    payload_not_available: "offline"
};
const device = {
    identifiers: ["node_red_vpn_monitoring"],
    name: "Monitoramento de VPN",
    manufacturer: "Node-RED",
    model: "Disponibilidade de túneis privados"
};
return [[
    {
        topic: "homeassistant/binary_sensor/vpn_primary_connection/config",
        payload: JSON.stringify({
            name: "Conexão VPN principal",
            object_id: "vpn_primary_connection",
            default_entity_id: "binary_sensor.vpn_primary_connection",
            unique_id: "node_red_vpn_primary_connection",
            device_class: "connectivity",
            state_topic: "nodered/infrastructure/vpn/vpn_primary/connection",
            json_attributes_topic: "nodered/infrastructure/vpn/vpn_primary/attributes",
            payload_on: "ON",
            payload_off: "OFF",
            ...availability,
            device
        })
    },
    {
        topic: "homeassistant/sensor/vpn_primary_connection_state/config",
        payload: JSON.stringify({
            name: "Estado da VPN principal",
            object_id: "vpn_primary_connection_state",
            default_entity_id: "sensor.vpn_primary_connection_state",
            unique_id: "node_red_vpn_primary_connection_state",
            icon: "mdi:vpn",
            entity_category: "diagnostic",
            state_topic: "nodered/infrastructure/vpn/vpn_primary/state",
            json_attributes_topic: "nodered/infrastructure/vpn/vpn_primary/attributes",
            ...availability,
            device
        })
    }
]];

for (const key of [
    "vpn_monitor_report_v1__test",
    "vpn_monitor_internet_v1__test",
    "vpn_monitor_state_v1__test",
    "vpn_monitor_last_dry_run_v1"
]) flow.set(key, undefined);
flow.set("vpn_monitor_last_dry_run_v1", {
    version: 1,
    reset: true,
    simulated: true,
    dispatched: false,
    events: [],
    completed_at: Date.now()
});
node.status({ fill: "grey", shape: "ring", text: "estado de teste resetado" });
return null;

if (msg._vpn_test !== true) return null;
if (msg._vpn_test_kind === "internet") return [msg, null, null];
if (msg._vpn_test_kind === "report") return [null, msg, null];
if (msg._vpn_test_kind === "evaluate") return [null, null, msg];
return null;

const KEY = "vpn_monitor_last_dry_run_v1";
const previous = flow.get(KEY) ?? { events: [] };
const event = {
    simulated: true,
    dispatched: false,
    external_call_sent: false,
    notification_sent: false,
    observer_kind: msg.payload?.observer_kind ?? "unknown",
    side_effect: msg.payload?.side_effect ?? msg._vpn_side_effect ?? "unknown",
    completed_at: Date.now()
};
const events = [...(previous.events ?? []), event].slice(-20);
flow.set(KEY, { version: 1, events, ...event });
node.status({ fill: "blue", shape: "dot", text: `TESTE ${event.observer_kind}: bloqueado` });
return null;

const TEST_MODE =
    msg._global_observer_test === true ||
    msg.payload?.test_mode === true;
const STATE_KEY = TEST_MODE
    ? "global_flow_observer_v1__test"
    : "global_flow_observer_v1";
const STORE = TEST_MODE ? undefined : "persistent";
const now = Number(msg.observer_now ?? Date.now());
const getState = () => STORE
    ? flow.get(STATE_KEY, STORE)
    : flow.get(STATE_KEY);
const setState = (value) => STORE
    ? flow.set(STATE_KEY, value, STORE)
    : flow.set(STATE_KEY, value);
const previousState = getState();
const state = previousState?.version === 2
    ? previousState
    : {
        version: 2,
        errors: previousState?.errors ?? {},
        status_sources: {},
        status_incidents: {}
    };
state.errors = state.errors ?? {};
state.status_sources = state.status_sources ?? {};
state.status_incidents = state.status_incidents ?? {};

const observer = msg._global_observer ?? {};
const flowId = String(observer.flow_id ?? "unknown").slice(0, 100);
const flowLabel = String(observer.flow_label ?? "fluxo desconhecido")
    .replace(/[\r\n]+/g, " ")
    .slice(0, 100);
const source = msg.error?.source ?? msg.status?.source ?? {};
const sourceId = String(source.id ?? "unknown").slice(0, 100);
const sourceType = String(source.type ?? "unknown").slice(0, 80);
const sourceName = String(source.name || sourceType || "nó desconhecido")
    .replace(/[\r\n]+/g, " ")
    .slice(0, 100);

function hash(value) {
    let result = 0x811c9dc5;
    for (const character of String(value)) {
        result ^= character.charCodeAt(0);
        result = Math.imul(result, 0x01000193) >>> 0;
    }
    return result.toString(16).padStart(8, "0");
}

function failureClass(value) {
    const text = String(value ?? "").toLowerCase();
    if (/(?:401|unauthori[sz]ed|authentic|credencial)/.test(text)) {
        return "autenticação";
    }
    if (/(?:timeout|timed out|tempo limite)/.test(text)) return "timeout";
    if (/(?:disconnect|offline|unavailable|indispon|sem conexão)/.test(text)) {
        return "indisponibilidade";
    }
    return "erro de execução";
}

if (msg.error) {
    const errorText = String(msg.error.message ?? "erro desconhecido");
    const classification = failureClass(errorText);
    const signature = hash(`${flowId}:${sourceId}:${classification}:${errorText}`);
    const key = `${flowId}:${sourceId}:${signature}`;
    const previous = state.errors[key] ?? {};
    const notificationDue =
        !Number.isFinite(previous.notified_at) ||
        now - previous.notified_at >= 6 * 60 * 60 * 1000;
    state.errors[key] = {
        flow_id: flowId,
        flow_label: flowLabel,
        source_id: sourceId,
        source_type: sourceType,
        source_name: sourceName,
        failure_class: classification,
        first_seen_at: previous.first_seen_at ?? now,
        last_seen_at: now,
        notified_at: notificationDue ? now : previous.notified_at
    };
    for (const [entryKey, entry] of Object.entries(state.errors)) {
        if (now - Number(entry.last_seen_at ?? now) > 7 * 24 * 60 * 60 * 1000) {
            delete state.errors[entryKey];
        }
    }
    setState(state);
    if (!notificationDue) return null;
    msg.payload = {
        test_mode: TEST_MODE,
        observer_kind: "node_error",
        flow_id: flowId,
        source_id: sourceId
    };
    msg.alert = {
        title: TEST_MODE
            ? "TESTE — Falha em fluxo Node-RED"
            : "Falha em fluxo Node-RED",
        message:
            `O fluxo “${flowLabel}” registrou ${classification} no nó ` +
            `“${sourceName}”. O mesmo erro será silenciado por 6 horas ` +
            "para evitar notificações repetidas."
    };
    return msg;
}

if (msg.status) {
    const text = String(msg.status.text ?? "").toLowerCase();
    const haTypes = new Set([
        "api-call-service",
        "api-current-state",
        "api-get-history",
        "api-render-template",
        "events-all",
        "ha-api",
        "poll-state",
        "server-events",
        "server-state-changed",
        "trigger-state"
    ]);
    const monitoredConnectionType =
        haTypes.has(sourceType) ||
        sourceType.startsWith("ha-") ||
        sourceType === "mqtt in" ||
        sourceType === "mqtt out" ||
        sourceType === "DuloNodeDevice" ||
        sourceType === "DuloNodeHub";
    if (!monitoredConnectionType) {
        delete state.status_sources[`${flowId}:${sourceId}`];
        setState(state);
        return null;
    }
    const sharedConnectionType =
        haTypes.has(sourceType) ||
        sourceType.startsWith("ha-") ||
        sourceType === "mqtt in" ||
        sourceType === "mqtt out";
    const connectionFailure =
        /(?:disconnect|not connected|connection (?:lost|error|failed|timed out)|offline|unavailable|indispon|sem conexão|desconect|connecting|conectando)/.test(text);
    const nodeFailure =
        connectionFailure ||
        msg.status.fill === "red" ||
        /(?:error|failed|failure|timed out|timeout|falhou)/.test(text);
    // HA nodes also use red status for domain conditions and rejected service
    // calls. Those failures are handled by catch and must not masquerade as a
    // shared Home Assistant outage.
    const failing = sharedConnectionType ? connectionFailure : nodeFailure;
    let incidentKey = `node:${flowId}:${sourceId}`;
    let incidentKind = "node_status";
    if (haTypes.has(sourceType) || sourceType.startsWith("ha-")) {
        incidentKey = "connection:home_assistant";
        incidentKind = "home_assistant";
    } else if (sourceType === "mqtt in" || sourceType === "mqtt out") {
        incidentKey = "connection:mqtt";
        incidentKind = "mqtt";
    }
    const key = `${flowId}:${sourceId}`;
    if (failing) {
        const previous = state.status_sources[key];
        state.status_sources[key] = {
            flow_id: flowId,
            flow_label: flowLabel,
            source_id: sourceId,
            source_type: sourceType,
            source_name: sourceName,
            incident_key: incidentKey,
            incident_kind: incidentKind,
            first_seen_at:
                previous?.incident_key === incidentKey
                    ? previous.first_seen_at
                    : now,
            last_seen_at: now
        };
    } else {
        delete state.status_sources[key];
    }
    setState(state);
}

return null;

const TEST_MODE =
    msg._global_observer_test === true ||
    msg.payload?.test_mode === true;
const STATE_KEY = TEST_MODE
    ? "global_flow_observer_v1__test"
    : "global_flow_observer_v1";
const STORE = TEST_MODE ? undefined : "persistent";
const now = Number(msg.observer_now ?? Date.now());
const getState = () => STORE
    ? flow.get(STATE_KEY, STORE)
    : flow.get(STATE_KEY);
const setState = (value) => STORE
    ? flow.set(STATE_KEY, value, STORE)
    : flow.set(STATE_KEY, value);
const previousState = getState();
const state = previousState?.version === 2
    ? previousState
    : {
        version: 2,
        errors: previousState?.errors ?? {},
        status_sources: {},
        status_incidents: {}
    };
state.status_sources = state.status_sources ?? {};
state.status_incidents = state.status_incidents ?? {};

const grouped = new Map();
for (const source of Object.values(state.status_sources)) {
    const key = source.incident_key;
    const current = grouped.get(key) ?? {
        kind: source.incident_kind,
        first_seen_at: Number(source.first_seen_at ?? now),
        sources: []
    };
    current.first_seen_at = Math.min(
        current.first_seen_at,
        Number(source.first_seen_at ?? now)
    );
    current.sources.push(source);
    grouped.set(key, current);
}

const alerts = [];
for (const [key, incident] of grouped) {
    if (now - incident.first_seen_at < 60 * 1000) continue;
    const previous = state.status_incidents[key] ?? {};
    const notificationDue =
        !Number.isFinite(previous.notified_at) ||
        now - previous.notified_at >= 6 * 60 * 60 * 1000;
    state.status_incidents[key] = {
        kind: incident.kind,
        first_seen_at: previous.first_seen_at ?? incident.first_seen_at,
        last_seen_at: now,
        notified_at: notificationDue ? now : previous.notified_at
    };
    if (!notificationDue) continue;

    const first = incident.sources[0];
    let title = "Nó Node-RED indisponível";
    let message =
        `O nó “${first.source_name}” do fluxo “${first.flow_label}” ` +
        "permanece em estado de falha há pelo menos 1 minuto.";
    if (incident.kind === "home_assistant") {
        title = "Node-RED sem Home Assistant";
        message =
            "Os fluxos perderam a conexão com o Home Assistant por pelo " +
            "menos 1 minuto. As chamadas configuradas com fila serão " +
            "retomadas e este push será entregue quando a conexão voltar.";
    } else if (incident.kind === "mqtt") {
        title = "Node-RED sem MQTT";
        message =
            "Os fluxos perderam a conexão com o broker MQTT por pelo menos " +
            "1 minuto. Verifique o Mosquitto e a rede local.";
    }
    alerts.push({
        _global_observer_test: TEST_MODE,
        payload: {
            test_mode: TEST_MODE,
            observer_kind: "node_unavailable",
            incident_key: key
        },
        alert: {
            title: TEST_MODE ? `TESTE — ${title}` : title,
            message
        }
    });
}

for (const key of Object.keys(state.status_incidents)) {
    if (!grouped.has(key)) delete state.status_incidents[key];
}
setState(state);
return [alerts.length ? alerts : null];

const TEST_MODE =
    msg._global_observer_test === true ||
    msg.payload?.test_mode === true;
const DELIVERY_TEST = msg._observer_delivery_test === true;

if (TEST_MODE && !DELIVERY_TEST) return [null, msg];

if (DELIVERY_TEST) {
    msg.payload = {
        ...(msg.payload ?? {}),
        test_mode: true,
        notification_delivery_under_test: true
    };
    msg.alert = {
        title: "TESTE — Monitor global do Node-RED",
        message:
            "TESTE de entrega: o canal central de falhas dos fluxos " +
            "Node-RED conseguiu solicitar esta notificação ao Home Assistant."
    };
}
return [msg, null];

const deliveryTest = msg._observer_delivery_test === true;
node.log("NODERED_GLOBAL_NOTIFICATION_ACCEPTED kind=" + String(msg.payload?.observer_kind ?? "unknown") + " delivery_test=" + String(deliveryTest));
return null;

flow.set("global_flow_observer_v1__test", undefined);
flow.set("global_flow_observer_last_dry_run_v1", {
